window.QBANK = window.QBANK || {};
window.QBANK["sma-biologi"] = {
  level: "SMA", subject: "Biologi", duration: 900,
  questions: [
    { q: "Organel sel yang menjadi tempat berlangsungnya fotosintesis adalah ...", options: ["mitokondria", "kloroplas", "nukleus", "ribosom"], answer: 1, solution: "Langkah 1: fotosintesis memerlukan klorofil untuk menangkap energi cahaya. Langkah 2: klorofil tersimpan di dalam kloroplas. Langkah 3: jadi fotosintesis berlangsung di kloroplas." },
    { q: "Persilangan monohibrid Aa × Aa menghasilkan perbandingan fenotipe ...", options: ["1 : 1", "9 : 3 : 3 : 1", "3 : 1", "1 : 2 : 1"], answer: 2, solution: "Langkah 1: buat kotak Punnett Aa × Aa, diperoleh genotipe AA, Aa, Aa, aa. Langkah 2: fenotipe dominan (A_) ada 3, fenotipe resesif (aa) ada 1. Langkah 3: perbandingan fenotipe $= 3 : 1$. (Catatan: $1 : 2 : 1$ adalah perbandingan genotipe.)" },
    { q: "Persilangan antara tanaman bergenotipe MM dan mm akan menghasilkan keturunan ...", options: ["100% Mm", "50% MM : 50% mm", "100% mm", "75% MM : 25% mm"], answer: 0, solution: "Langkah 1: induk MM hanya dapat menghasilkan gamet M, induk mm hanya gamet m. Langkah 2: semua pasangan gamet menghasilkan genotipe Mm. Langkah 3: jadi 100% keturunan bergenotipe Mm (semuanya berfenotipe dominan)." },
    { q: "Organel sel yang berfungsi sebagai tempat respirasi sel dan penghasil ATP adalah ...", options: ["kloroplas", "lisosom", "badan Golgi", "mitokondria"], answer: 3, solution: "Langkah 1: respirasi sel bertujuan menghasilkan energi dalam bentuk ATP. Langkah 2: organel yang memiliki sistem untuk menghasilkan ATP adalah mitokondria. Langkah 3: jadi jawabannya mitokondria." },
    { q: "Dalam suatu ekosistem, yang berperan sebagai produsen adalah ...", options: ["herbivora", "karnivora", "tumbuhan hijau", "pengurai"], answer: 2, solution: "Langkah 1: produsen adalah organisme yang dapat membuat makanannya sendiri. Langkah 2: hanya tumbuhan hijau yang berfotosintesis untuk membuat makanan sendiri. Langkah 3: jadi produsen = tumbuhan hijau." },
    { q: "Persilangan dihibrid AaBb × AaBb menghasilkan perbandingan fenotipe ...", options: ["9 : 3 : 3 : 1", "3 : 1", "1 : 1", "1 : 2 : 1"], answer: 0, solution: "Langkah 1: buat kotak Punnett $4 \\times 4$ untuk AaBb × AaBb, total 16 kotak. Langkah 2: hitung tiap fenotipe: dominan-dominan 9, dominan-resesif 3, resesif-dominan 3, resesif-resesif 1. Langkah 3: perbandingannya $9 : 3 : 3 : 1$." },
    { q: "Jumlah kromosom pada sel tubuh manusia adalah ...", options: ["23", "44", "48", "46"], answer: 3, solution: "Langkah 1: sel tubuh manusia bersifat diploid (2n). Langkah 2: jumlah kromosom haploid manusia $n = 23$. Langkah 3: $2n = 2 \\times 23 = 46$ kromosom, atau 23 pasang." },
    { q: "Struktur sel yang hanya dimiliki oleh sel tumbuhan dan tidak dimiliki sel hewan adalah ...", options: ["membran sel", "dinding sel", "sitoplasma", "nukleus"], answer: 1, solution: "Langkah 1: bandingkan struktur sel hewan dan sel tumbuhan. Langkah 2: keduanya memiliki membran sel, sitoplasma, dan nukleus. Langkah 3: hanya sel tumbuhan yang memiliki dinding sel." },
    { q: "Perhatikan rantai makanan: padi → belalang → katak → ular. Yang berperan sebagai konsumen tingkat II adalah ...", options: ["belalang", "ular", "katak", "padi"], answer: 2, solution: "Langkah 1: urutkan tingkat trofik: padi = produsen, belalang = konsumen I, katak = konsumen II, ular = konsumen III. Langkah 2: konsumen tingkat II adalah organisme yang memakan konsumen I. Langkah 3: jadi jawabannya katak." },
    { q: "Basa nitrogen penyusun DNA adalah ...", options: ["adenin, urasil, guanin, sitosin", "adenin, timin, guanin, sitosin", "adenin, timin, guanin, urasil", "guanin, sitosin, timin, timin"], answer: 1, solution: "Langkah 1: DNA tersusun dari empat basa nitrogen. Langkah 2: ingat pasangan basanya, A–T dan G–C. Langkah 3: jadi basa nitrogen DNA = adenin, timin, guanin, sitosin. (Urasil hanya ada di RNA.)" },
    { q: "Organel sel yang berfungsi mencerna zat asing dan organel rusak (autofagi) adalah ...", options: ["ribosom", "lisosom", "vakuola", "sentrosom"], answer: 1, solution: "Langkah 1: pencernaan intrasel memerlukan enzim hidrolitik. Langkah 2: lisosom mengandung enzim hidrolitik untuk mencerna zat asing, sisa metabolisme, dan organel rusak. Langkah 3: jadi organel tersebut adalah lisosom." },
    { q: "Jaringan pada tumbuhan yang berfungsi mengangkut air dan mineral dari akar ke daun adalah ...", options: ["floem", "xilem", "parenkim", "kolenkim"], answer: 1, solution: "Langkah 1: tumbuhan memiliki dua jaringan pengangkut: xilem dan floem. Langkah 2: floem mengangkut hasil fotosintesis dari daun ke seluruh tubuh. Langkah 3: xilem mengangkut air dan mineral dari akar ke daun." },
    { q: "Pertukaran gas O₂ dan CO₂ di paru-paru terjadi pada bagian ...", options: ["bronkus", "trakea", "alveolus", "laring"], answer: 2, solution: "Langkah 1: udara masuk melalui trakea → bronkus → bronkiolus. Langkah 2: di ujung bronkiolus terdapat gelembung-gelembung kecil berdinding tipis bernama alveolus. Langkah 3: difusi O₂ dan CO₂ antara udara dan darah terjadi di alveolus." },
    { q: "Penyerapan sari-sari makanan (nutrisi) terutama terjadi di ...", options: ["lambung", "usus halus", "usus besar", "kerongkongan"], answer: 1, solution: "Langkah 1: makanan dicerna secara kimiawi hingga menjadi molekul sederhana. Langkah 2: usus halus memiliki vili (jonjot) yang memperluas bidang penyerapan. Langkah 3: jadi penyerapan sari makanan terutama terjadi di usus halus." },
    { q: "Pembuluh darah yang membawa darah kaya oksigen dari paru-paru menuju jantung adalah ...", options: ["vena pulmonalis", "arteri pulmonalis", "vena cava", "aorta"], answer: 0, solution: "Langkah 1: darah yang sudah mengambil O₂ di paru-paru harus kembali ke jantung. Langkah 2: pembuluh yang menuju jantung disebut vena; vena pulmonalis membawa darah kaya O₂. Langkah 3: arteri pulmonalis justru membawa darah kaya CO₂ dari jantung ke paru-paru." },
    { q: "Unit terkecil penyusun sistem saraf yang berfungsi menghantarkan impuls adalah ...", options: ["nefron", "neuron", "akson", "sinapsis"], answer: 1, solution: "Langkah 1: sistem saraf tersusun dari sel-sel saraf. Langkah 2: sel saraf (neuron) adalah unit terkecil yang mampu menerima dan menghantarkan impuls. Langkah 3: nefron adalah unit ginjal, sedangkan akson dan sinapsis adalah bagian dari neuron." },
    { q: "Organ pada manusia yang berfungsi menyaring darah dan membentuk urine adalah ...", options: ["hati", "ginjal", "kulit", "paru-paru"], answer: 1, solution: "Langkah 1: darah membawa sisa metabolisme seperti urea yang harus dibuang. Langkah 2: ginjal menyaring darah melalui nefron dan menghasilkan urine. Langkah 3: jadi organ pembentuk urine adalah ginjal." },
    { q: "Sifat makhluk hidup yang dapat diamati dari luar, misalnya warna bunga merah, disebut ...", options: ["genotipe", "fenotipe", "alel", "lokus"], answer: 1, solution: "Langkah 1: sifat organisme ditentukan oleh susunan gen (genotipe). Langkah 2: penampakan fisik sifat tersebut yang terlihat dari luar disebut fenotipe. Langkah 3: jadi warna bunga merah adalah contoh fenotipe." },
    { q: "Buta warna terpaut kromosom X dan bersifat resesif. Ayah normal menikah dengan ibu normal yang carier. Peluang anak laki-laki mereka menderita buta warna adalah ...", options: ["$0\\%$", "$25\\%$", "$50\\%$", "$100\\%$"], answer: 2, solution: "Langkah 1: genotipe ayah $X^B Y$ dan ibu $X^B X^b$. Langkah 2: anak laki-laki menerima kromosom X dari ibu: $X^B$ (normal) atau $X^b$ (buta warna). Langkah 3: peluang menerima $X^b$ adalah $\\frac{1}{2} = 50\\%$." },
    { q: "Ayah bergolongan darah A heterozigot menikah dengan ibu bergolongan darah O. Golongan darah yang mungkin dimiliki anak-anak mereka adalah ...", options: ["A dan O", "A dan B", "B dan O", "AB saja"], answer: 0, solution: "Langkah 1: genotipe ayah $I^A i$ dan ibu $ii$. Langkah 2: kemungkinan genotipe anak: $I^A i$ (golongan A) dan $ii$ (golongan O). Langkah 3: jadi anak-anak mereka bergolongan darah A atau O." },
    { q: "Ilmuwan yang mencetuskan teori evolusi melalui seleksi alam adalah ...", options: ["Lamarck", "Darwin", "Mendel", "Weismann"], answer: 1, solution: "Langkah 1: beberapa ilmuwan mengemukakan gagasan evolusi. Langkah 2: Charles Darwin dalam bukunya menjelaskan evolusi terjadi melalui seleksi alam. Langkah 3: jadi pencetus teori seleksi alam adalah Darwin." },
    { q: "Berikut ini yang merupakan contoh seleksi alam adalah ...", options: ["munculnya hama resisten akibat penggunaan pestisida", "pemuliaan padi unggul oleh petani", "kloning domba", "kultur jaringan tanaman anggrek"], answer: 0, solution: "Langkah 1: seleksi alam adalah seleksi oleh faktor lingkungan tanpa campur tangan manusia. Langkah 2: hama yang tahan pestisida bertahan hidup dan berkembang biak, sedangkan yang tidak tahan mati. Langkah 3: pemuliaan, kloning, dan kultur jaringan adalah campur tangan manusia (seleksi buatan)." },
    { q: "Hubungan antara tumbuhan benalu dan pohon inangnya merupakan simbiosis ...", options: ["mutualisme", "komensalisme", "parasitisme", "netralisme"], answer: 2, solution: "Langkah 1: benalu menempel pada inang dan mengambil air serta zat hara dari inangnya. Langkah 2: benalu diuntungkan, sedangkan pohon inang dirugikan. Langkah 3: hubungan untung-rugi seperti ini disebut simbiosis parasitisme." },
    { q: "Dalam daur nitrogen, bakteri yang mengubah amonia menjadi nitrit adalah bakteri ...", options: ["denitrifikasi", "nitrifikasi", "fiksasi", "ammonifikasi"], answer: 1, solution: "Langkah 1: daur nitrogen melibatkan beberapa kelompok bakteri. Langkah 2: bakteri nitrifikasi (Nitrosomonas) mengoksidasi amonia menjadi nitrit, lalu menjadi nitrat. Langkah 3: jadi jawabannya bakteri nitrifikasi." },
    { q: "Varietas padi IR64, Ciherang, dan Pandan Wangi menunjukkan keanekaragaman hayati tingkat ...", options: ["gen", "jenis", "ekosistem", "populasi"], answer: 0, solution: "Langkah 1: ketiga varietas tersebut termasuk spesies yang sama, yaitu padi. Langkah 2: perbedaan antarvarietas dalam satu spesies disebabkan perbedaan susunan gen. Langkah 3: jadi ini contoh keanekaragaman tingkat gen." },
    { q: "Hutan hujan tropis, hutan bakau, dan padang rumput menunjukkan keanekaragaman hayati tingkat ...", options: ["gen", "jenis", "ekosistem", "individu"], answer: 2, solution: "Langkah 1: ketiganya adalah lingkungan hidup yang berbeda dengan komunitas berbeda. Langkah 2: perbedaan antarlingkungan hidup beserta interaksinya menunjukkan keanekaragaman ekosistem. Langkah 3: jadi jawabannya tingkat ekosistem." },
    { q: "Berikut ini yang merupakan produk bioteknologi konvensional adalah ...", options: ["tempe", "insulin hasil rekayasa", "vaksin mRNA", "tanaman transgenik"], answer: 0, solution: "Langkah 1: bioteknologi konvensional memanfaatkan mikroorganisme secara langsung tanpa rekayasa genetika. Langkah 2: tempe dibuat melalui fermentasi kedelai oleh jamur Rhizopus. Langkah 3: insulin, vaksin mRNA, dan tanaman transgenik adalah produk bioteknologi modern." },
    { q: "Dalam teknik rekayasa genetika, enzim yang berfungsi memotong dan menyambung kembali DNA berturut-turut adalah ...", options: ["ligase saja", "restriksi dan ligase", "polimerase saja", "amilase"], answer: 1, solution: "Langkah 1: rekayasa genetika memerlukan pemotongan DNA pada urutan tertentu. Langkah 2: enzim restriksi (endonuklease) memotong DNA, sedangkan enzim ligase menyambung potongan DNA. Langkah 3: jadi enzim yang digunakan berturut-turut adalah restriksi dan ligase." },
    { q: "Perbedaan utama antara sel prokariotik dan sel eukariotik adalah ...", options: ["adanya dinding sel", "adanya membran inti sel", "ukuran sel", "adanya ribosom"], answer: 1, solution: "Langkah 1: sel prokariotik (misalnya bakteri) memiliki materi genetik yang tersebar di sitoplasma. Langkah 2: sel eukariotik memiliki inti sel yang dibungkus membran inti. Langkah 3: jadi perbedaan utamanya adalah adanya membran inti sel." },
    { q: "Hormon insulin yang mengatur kadar gula darah dihasilkan oleh ...", options: ["hati", "pankreas", "ginjal", "kelenjar tiroid"], answer: 1, solution: "Langkah 1: insulin adalah hormon penurun kadar glukosa darah. Langkah 2: insulin dihasilkan oleh sel beta di pulau Langerhans. Langkah 3: pulau Langerhans terletak di pankreas, jadi insulin dihasilkan pankreas." },
    { q: "Urutan jalannya impuls pada gerak refleks yang benar adalah ...", options: ["reseptor – neuron sensorik – sumsum tulang belakang – neuron motorik – efektor", "reseptor – neuron sensorik – otak – neuron motorik – efektor", "efektor – neuron motorik – sumsum tulang belakang – neuron sensorik – reseptor", "reseptor – neuron motorik – sumsum tulang belakang – neuron sensorik – efektor"], answer: 0, solution: "Langkah 1: rangsang diterima reseptor lalu dibawa neuron sensorik ke pusat saraf. Langkah 2: pada gerak refleks, impuls tidak diolah di otak melainkan langsung di sumsum tulang belakang. Langkah 3: dari sumsum tulang belakang impuls diteruskan neuron motorik ke efektor (otot/kelenjar) sehingga terjadi gerakan yang cepat." },
    { q: "Bagian neuron yang berfungsi menerima impuls dari sel saraf lain dan meneruskannya ke badan sel adalah ...", options: ["akson", "sinapsis", "dendrit", "nodus Ranvier"], answer: 2, solution: "Langkah 1: neuron tersusun dari dendrit, badan sel, dan akson. Langkah 2: dendrit adalah serabut pendek bercabang yang menerima impuls. Langkah 3: impuls dari dendrit diteruskan ke badan sel lalu ke akson. (Akson justru meneruskan impuls menjauhi badan sel.)" },
    { q: "Bagian otak yang berfungsi mengatur keseimbangan tubuh dan koordinasi gerakan otot adalah ...", options: ["otak besar (serebrum)", "sumsum lanjutan (medula oblongata)", "hipotalamus", "otak kecil (serebelum)"], answer: 3, solution: "Langkah 1: otak besar adalah pusat kesadaran dan kecerdasan, sedangkan sumsum lanjutan mengatur pernapasan dan detak jantung. Langkah 2: otak kecil (serebelum) menerima informasi tentang posisi tubuh. Langkah 3: serebelum mengoordinasikan gerakan otot dan menjaga keseimbangan tubuh." },
    { q: "Hormon tiroksin yang mengatur laju metabolisme tubuh dihasilkan oleh kelenjar ...", options: ["pankreas", "adrenal", "tiroid", "hipofisis"], answer: 2, solution: "Langkah 1: tiroksin adalah hormon pengatur metabolisme yang pembentukannya memerlukan iodin. Langkah 2: tiroksin dihasilkan oleh kelenjar tiroid (kelenjar gondok) di leher. Langkah 3: kekurangan iodin mengganggu pembentukan tiroksin sehingga kelenjar tiroid membesar (gondok)." },
    { q: "Saat terkejut atau ketakutan, tubuh melepaskan hormon adrenalin. Hormon ini dihasilkan oleh ...", options: ["kelenjar adrenal (anak ginjal)", "kelenjar tiroid", "pankreas", "kelenjar hipofisis"], answer: 0, solution: "Langkah 1: adrenalin adalah hormon keadaan darurat yang menyiapkan tubuh menghadapi bahaya. Langkah 2: hormon ini dihasilkan oleh bagian medula kelenjar adrenal (anak ginjal). Langkah 3: adrenalin meningkatkan detak jantung, tekanan darah, dan kadar gula darah." },
    { q: "Sel kerucut (konus) pada retina mata berfungsi untuk ...", options: ["melihat dalam keadaan gelap", "mengatur banyaknya cahaya yang masuk", "meneruskan bayangan ke otak", "melihat warna dan detail benda"], answer: 3, solution: "Langkah 1: retina memiliki dua fotoreseptor, yaitu sel batang (basilus) dan sel kerucut (konus). Langkah 2: sel batang peka terhadap cahaya redup (penglihatan malam), sedangkan sel kerucut peka terhadap warna. Langkah 3: jadi sel kerucut berfungsi untuk melihat warna dan detail benda." },
    { q: "Spermatogenesis, yaitu pembentukan sel sperma, berlangsung di ...", options: ["epididimis", "vas deferens", "tubulus seminiferus testis", "kelenjar prostat"], answer: 2, solution: "Langkah 1: sperma dihasilkan di organ reproduksi jantan, yaitu testis. Langkah 2: di dalam testis terdapat saluran-saluran halus bernama tubulus seminiferus. Langkah 3: di dinding tubulus seminiferus inilah spermatogonium berkembang menjadi sperma." },
    { q: "Oogenesis (pembentukan sel telur) pada wanita terjadi di ...", options: ["ovarium", "uterus", "tuba falopi", "vagina"], answer: 0, solution: "Langkah 1: sel telur (ovum) dihasilkan oleh organ reproduksi betina. Langkah 2: organ penghasil sel telur adalah ovarium (indung telur). Langkah 3: di dalam ovarium, oogonium berkembang menjadi ovum melalui proses oogenesis." },
    { q: "Fertilisasi (pembuahan) sel telur oleh sperma pada manusia umumnya terjadi di ...", options: ["uterus", "ovarium", "vagina", "tuba falopi"], answer: 3, solution: "Langkah 1: ovulasi melepaskan ovum dari ovarium ke tuba falopi. Langkah 2: sperma berenang dari vagina melalui uterus menuju tuba falopi. Langkah 3: pertemuan sperma dan ovum (fertilisasi) terjadi di tuba falopi, lalu zigot bergerak ke uterus untuk implantasi." },
    { q: "Hormon yang memicu terjadinya ovulasi (pelepasan ovum dari ovarium) adalah ...", options: ["FSH", "LH", "estrogen", "progesteron"], answer: 1, solution: "Langkah 1: FSH merangsang pematangan folikel, sedangkan estrogen dan progesteron mengatur siklus dan kehamilan. Langkah 2: menjelang ovulasi terjadi lonjakan hormon LH (luteinizing hormone). Langkah 3: lonjakan LH inilah yang memicu pecahnya folikel dan pelepasan ovum (ovulasi)." },
    { q: "Menstruasi terjadi karena ...", options: ["meningkatnya kadar estrogen dan progesteron", "terjadinya fertilisasi di tuba falopi", "menebalnya dinding endometrium", "meluruhnya dinding endometrium akibat menurunnya kadar estrogen dan progesteron"], answer: 3, solution: "Langkah 1: setiap siklus, endometrium (dinding rahim) menebal untuk persiapan kehamilan. Langkah 2: jika tidak terjadi fertilisasi, korpus luteum menyusut sehingga kadar estrogen dan progesteron turun. Langkah 3: turunnya kedua hormon membuat endometrium meluruh dan keluar sebagai darah menstruasi." },
    { q: "Sayap kelelawar, kaki depan kuda, dan tangan manusia memiliki struktur tulang dasar yang sama meskipun fungsinya berbeda. Organ-organ tersebut disebut organ ...", options: ["analog", "homolog", "vestigial", "rudimenter"], answer: 1, solution: "Langkah 1: organ homolog memiliki struktur dasar (asal embriologis) yang sama. Langkah 2: meskipun fungsinya berbeda (terbang, berlari, memegang), kesamaan struktur menunjukkan nenek moyang yang sama. Langkah 3: jadi organ tersebut adalah organ homolog, salah satu bukti evolusi." },
    { q: "Sayap kupu-kupu dan sayap burung memiliki fungsi sama (terbang) tetapi struktur dasarnya berbeda. Kedua organ tersebut merupakan contoh organ ...", options: ["homolog", "vestigial", "embriologis", "analog"], answer: 3, solution: "Langkah 1: organ analog memiliki fungsi sama tetapi struktur dasar dan asal embriologis berbeda. Langkah 2: sayap kupu-kupu berasal dari lipatan kitin, sedangkan sayap burung adalah modifikasi kaki depan bertulang. Langkah 3: kesamaan fungsi akibat adaptasi terhadap lingkungan yang sama ini disebut organ analog." },
    { q: "Sumber utama munculnya variasi genetik baru dalam suatu populasi adalah ...", options: ["seleksi alam", "penggunaan organ tubuh", "mutasi dan rekombinasi gen", "perubahan lingkungan"], answer: 2, solution: "Langkah 1: variasi genetik adalah bahan baku evolusi. Langkah 2: mutasi menciptakan alel baru, sedangkan rekombinasi saat reproduksi seksual mengacak kombinasi alel. Langkah 3: seleksi alam dan lingkungan hanya memilih variasi yang sudah ada, bukan menciptakannya." },
    { q: "Spesiasi adalah proses ...", options: ["terbentuknya spesies baru akibat isolasi reproduksi", "perubahan sifat individu selama hidupnya", "punahnya suatu spesies", "perpindahan populasi ke habitat baru"], answer: 0, solution: "Langkah 1: spesiasi adalah terbentuknya satu spesies atau lebih dari spesies asal. Langkah 2: populasi yang terisolasi (secara geografis atau reproduktif) mengalami akumulasi perbedaan genetik. Langkah 3: ketika isolasi reproduksi sudah sempurna, terbentuklah spesies baru." },
    { q: "Menurut teori Lamarck, leher jerapah menjadi panjang karena ...", options: ["jerapah berleher panjang lebih mudah bertahan hidup lalu terseleksi alam", "jerapah selalu menjangkau daun di tempat tinggi sehingga lehernya memanjang dan sifat itu diwariskan", "terjadi mutasi acak pada gen leher jerapah", "jerapah berleher pendek bermigrasi ke tempat lain"], answer: 1, solution: "Langkah 1: Lamarck mengemukakan teori use and disuse (pakai dan tidak pakai). Langkah 2: organ yang sering dipakai akan berkembang, lalu sifat yang diperoleh (acquired characters) diwariskan ke keturunan. Langkah 3: jadi menurut Lamarck, kebiasaan menjangkau daun di tempat tinggi membuat leher memanjang dan sifat itu diwariskan." },
    { q: "Prinsip dasar teknik kultur jaringan pada tumbuhan adalah ...", options: ["fermentasi oleh mikroorganisme", "hibridisasi dua varietas", "totipotensi sel tumbuhan", "mutasi buatan"], answer: 2, solution: "Langkah 1: kultur jaringan menumbuhkan potongan jaringan (eksplan) pada media steril. Langkah 2: teknik ini berhasil karena sel tumbuhan bersifat totipoten. Langkah 3: totipotensi artinya setiap sel tumbuhan berpotensi tumbuh menjadi individu yang utuh." },
    { q: "Dalam rekayasa genetika, plasmid bakteri berfungsi sebagai ...", options: ["enzim pemotong DNA", "vektor pembawa gen asing ke dalam sel inang", "media pertumbuhan bakteri", "sumber energi sel"], answer: 1, solution: "Langkah 1: rekayasa genetika memasukkan gen yang diinginkan ke sel inang. Langkah 2: gen asing memerlukan kendaraan untuk masuk ke sel inang, yaitu vektor. Langkah 3: plasmid (DNA sirkuler kecil bakteri) dipakai sebagai vektor karena mudah dipotong, disambung, dan digandakan di dalam bakteri." },
    { q: "Berikut ini dampak negatif penerapan bioteknologi modern, KECUALI ...", options: ["munculnya alergen baru pada produk transgenik", "meningkatnya produksi dan kualitas pangan", "terjadinya pencemaran genetik pada tanaman liar", "munculnya hama yang resisten terhadap insektisida"], answer: 1, solution: "Langkah 1: bioteknologi modern berisiko menimbulkan alergen baru, pencemaran genetik (gene flow), dan hama resisten. Langkah 2: ketiga hal tersebut merugikan manusia atau lingkungan. Langkah 3: meningkatnya produksi dan kualitas pangan justru merupakan dampak positif, bukan negatif." },
    { q: "Perbedaan mendasar bioteknologi modern dibandingkan bioteknologi konvensional adalah ...", options: ["memanfaatkan mikroorganisme secara langsung", "tidak menggunakan peralatan laboratorium", "menggunakan prinsip rekayasa genetika (DNA rekombinan)", "hanya menghasilkan produk pangan"], answer: 2, solution: "Langkah 1: bioteknologi konvensional memanfaatkan mikroorganisme utuh, misalnya fermentasi tempe dan tape. Langkah 2: bioteknologi modern memanipulasi materi genetik secara langsung melalui DNA rekombinan. Langkah 3: jadi perbedaan mendasarnya adalah penggunaan rekayasa genetika." },
    { q: "Fungsi utama membran sel adalah ...", options: ["tempat fotosintesis", "mengatur keluar masuknya zat", "sintesis protein", "respirasi seluler"], answer: 1, solution: "1. Membran sel bersifat selektif permeabel, artinya hanya zat tertentu yang boleh lewat. 2. Zat kecil seperti air dan oksigen dapat berdifusi, sedangkan zat lain diatur masuk-keluarnya. 3. Jadi fungsi utama membran sel adalah mengatur keluar masuknya zat." },
    { q: "Organel sel yang berfungsi sebagai tempat sintesis protein adalah ...", options: ["mitokondria", "ribosom", "lisosom", "badan Golgi"], answer: 1, solution: "1. Sintesis protein adalah proses perakitan asam amino menjadi protein berdasarkan kode mRNA. 2. Perakitan tersebut terjadi pada ribosom yang menempel di RE kasar atau melayang di sitoplasma. 3. Jadi organel tempat sintesis protein adalah ribosom." },
    { q: "Struktur sel yang mengendalikan seluruh kegiatan sel adalah ...", options: ["membran sel", "sitoplasma", "nukleus", "dinding sel"], answer: 2, solution: "1. Sel memerlukan pusat pengatur agar semua kegiatan berjalan terkoordinasi. 2. Di dalam nukleus terdapat DNA yang membawa instruksi untuk seluruh aktivitas sel. 3. Jadi struktur pengendali seluruh kegiatan sel adalah nukleus." },
    { q: "Hasil akhir dari proses glikolisis adalah ...", options: ["2 molekul asam piruvat", "1 molekul glukosa", "2 molekul asetil-KoA", "oksigen dan air"], answer: 0, solution: "1. Glikolisis adalah pemecahan glukosa (6 karbon) di sitoplasma. 2. Satu molekul glukosa dipecah menjadi dua molekul berkarbon tiga. 3. Jadi hasil akhirnya adalah 2 molekul asam piruvat beserta 2 ATP dan 2 NADH." },
    { q: "Dinding sel tumbuhan tersusun atas ...", options: ["selulosa", "kitin", "peptidoglikan", "kalsium karbonat"], answer: 0, solution: "1. Dinding sel memberi bentuk yang kokoh dan melindungi sel tumbuhan. 2. Komponen utama penyusunnya adalah serat polisakarida yang kuat. 3. Polisakarida tersebut adalah selulosa, sedangkan kitin penyusun dinding jamur dan peptidoglikan penyusun dinding bakteri." },
    { q: "Transpor zat yang memerlukan energi ATP adalah ...", options: ["difusi", "osmosis", "transpor aktif", "difusi terfasilitasi"], answer: 2, solution: "1. Difusi dan osmosis adalah transpor pasif yang mengikuti gradien konsentrasi tanpa energi. 2. Perpindahan zat melawan gradien konsentrasi membutuhkan pompa protein yang digerakkan energi. 3. Jadi transpor yang memerlukan energi ATP adalah transpor aktif." },
    { q: "Perpindahan molekul air melalui membran semipermeabel disebut ...", options: ["difusi", "osmosis", "imbibisi", "endositosis"], answer: 1, solution: "1. Difusi adalah perpindahan zat terlarut, sedangkan imbibisi adalah penyerapan air oleh zat padat. 2. Perpindahan khusus molekul air melewati membran semipermeabel dari larutan encer ke pekat memiliki nama tersendiri. 3. Peristiwa tersebut disebut osmosis." },
    { q: "Jika sel tumbuhan dimasukkan ke dalam larutan hipertonik, yang akan terjadi adalah ...", options: ["sel menjadi turgid", "sel mengalami lisis", "sel mengalami plasmolisis", "sel mengalami deplasmolisis"], answer: 2, solution: "1. Larutan hipertonik memiliki konsentrasi zat terlarut lebih tinggi daripada isi sel. 2. Akibat osmosis, air keluar dari sel sehingga membran sel terlepas dari dinding sel. 3. Peristiwa lepasnya membran dari dinding sel ini disebut plasmolisis." },
    { q: "Urutan tahapan pembelahan mitosis yang benar adalah ...", options: ["profase - metafase - anafase - telofase", "metafase - profase - telofase - anafase", "anafase - telofase - profase - metafase", "telofase - anafase - metafase - profase"], answer: 0, solution: "1. Pembelahan diawali profase saat kromatin memadat menjadi kromosom. 2. Kemudian kromosom berjejer di bidang ekuator (metafase) lalu kromatid memisah (anafase). 3. Terakhir sel membelah menjadi dua pada telofase, sehingga urutannya profase - metafase - anafase - telofase." },
    { q: "Pembelahan meiosis menghasilkan ...", options: ["2 sel anakan diploid", "4 sel anakan haploid", "4 sel anakan diploid", "2 sel anakan haploid"], answer: 1, solution: "1. Meiosis terdiri atas dua kali pembelahan (meiosis I dan II). 2. Pada meiosis I jumlah kromosom direduksi menjadi separuhnya (haploid). 3. Dari satu sel diploid dihasilkan 4 sel anakan yang haploid." },
    { q: "Pindah silang (crossing over) pada meiosis terjadi pada tahap ...", options: ["profase I", "metafase I", "anafase II", "telofase II"], answer: 0, solution: "1. Pindah silang adalah pertukaran segmen kromatid antara kromosom homolog. 2. Kromosom homolog berpasangan (sinapsis) pada awal meiosis I. 3. Peristiwa ini terjadi pada tahap profase I, tepatnya sub-tahap pakiten." },
    { q: "Jaringan meristem pada tumbuhan berfungsi untuk ...", options: ["fotosintesis", "pertumbuhan karena selnya aktif membelah", "pengangkutan air dan mineral", "penyimpanan cadangan makanan"], answer: 1, solution: "1. Pertumbuhan tumbuhan berpusat pada titik tumbuh di ujung akar dan ujung batang. 2. Di titik tumbuh terdapat sel-sel muda yang terus-menerus membelah. 3. Jaringan yang selnya aktif membelah ini disebut meristem dan berfungsi untuk pertumbuhan." },
    { q: "Floem mengangkut hasil fotosintesis dari ... ke ...", options: ["daun ke seluruh bagian tubuh", "akar ke daun", "batang ke akar saja", "bunga ke daun"], answer: 0, solution: "1. Hasil fotosintesis (gula) dibuat di daun sebagai sumber (source). 2. Gula tersebut dibutuhkan oleh akar, batang, buah, dan bagian lain sebagai pengguna (sink). 3. Jadi floem mengangkut hasil fotosintesis dari daun ke seluruh bagian tubuh." },
    { q: "Jaringan epitel pada hewan berfungsi untuk ...", options: ["kontraksi dan gerakan", "melapisi dan melindungi permukaan tubuh", "menghantarkan impuls saraf", "menyokong dan mengikat jaringan"], answer: 1, solution: "1. Permukaan tubuh dan organ dalam memerlukan pelapis pelindung. 2. Jaringan epitel tersusun atas sel-sel rapat yang melapisi permukaan tersebut. 3. Jadi fungsi jaringan epitel adalah melapisi dan melindungi permukaan tubuh atau organ." },
    { q: "Jaringan hewan yang berfungsi menghantarkan rangsang (impuls) adalah jaringan ...", options: ["otot", "saraf", "ikat", "epitel"], answer: 1, solution: "1. Rangsang dari lingkungan harus diteruskan ke saraf pusat lalu ke efektor. 2. Penghantar khusus rangsang berupa impuls listrik adalah sel neuron. 3. Kumpulan neuron membentuk jaringan saraf yang berfungsi menghantarkan impuls." },
    { q: "Sel darah merah (eritrosit) manusia dewasa tidak memiliki ...", options: ["hemoglobin", "membran sel", "inti sel", "sitoplasma"], answer: 2, solution: "1. Eritrosit berfungsi mengangkut oksigen dengan hemoglobin. 2. Agar ruang untuk hemoglobin maksimal, eritrosit kehilangan intinya saat dewasa. 3. Jadi eritrosit manusia dewasa tidak memiliki inti sel." },
    { q: "Penyakit Tay-Sachs berkaitan dengan kegagalan fungsi organel ...", options: ["lisosom", "ribosom", "mitokondria", "kloroplas"], answer: 0, solution: "1. Penyakit Tay-Sachs adalah kelainan bawaan akibat penumpukan lipid di sel saraf. 2. Penumpukan terjadi karena enzim pencerna di dalam sel tidak bekerja. 3. Enzim pencerna intraseluler terdapat di lisosom, sehingga penyakit ini berkaitan dengan kegagalan lisosom." },
    { q: "Badan Golgi pada sel berfungsi untuk ...", options: ["sintesis protein", "pengemasan dan sekresi protein", "respirasi seluler", "fotosintesis"], answer: 1, solution: "1. Protein yang dibuat ribosom perlu dimodifikasi dan dikirim ke tujuannya. 2. Protein melewati RE lalu menuju tumpukan membran pipih untuk dikemas dalam vesikula. 3. Tumpukan membran tersebut adalah badan Golgi yang berfungsi mengemas dan mensekresi protein." },
    { q: "Tulang tengkorak manusia termasuk jenis tulang ...", options: ["pipa", "pipih", "pendek", "tidak beraturan"], answer: 1, solution: "1. Tulang tengkorak berbentuk lempengan tipis dan lebar. 2. Tulang berbentuk lempengan berfungsi melindungi organ di baliknya, yaitu otak. 3. Tulang berbentuk lempengan tipis digolongkan sebagai tulang pipih." },
    { q: "Tulang paha (femur) termasuk jenis tulang ...", options: ["pipa", "pipih", "pendek", "sesamoid"], answer: 0, solution: "1. Tulang paha berbentuk silinder panjang dengan rongga berisi sumsum di tengahnya. 2. Tulang berbentuk pipa panjang dengan rongga sumsum disebut tulang pipa. 3. Jadi tulang paha termasuk tulang pipa." },
    { q: "Persendian yang memungkinkan gerakan ke segala arah adalah sendi ...", options: ["engsel", "peluru", "putar", "geser"], answer: 1, solution: "1. Sendi bahu dan panggul dapat digerakkan memutar ke segala arah. 2. Bentuknya seperti bola yang masuk ke dalam mangkok sehingga bebas bergerak. 3. Sendi berbentuk bola dan mangkok ini disebut sendi peluru." },
    { q: "Sendi pada siku dan lutut termasuk sendi ...", options: ["peluru", "engsel", "putar", "pelana"], answer: 1, solution: "1. Siku hanya dapat ditekuk dan diluruskan pada satu bidang gerak. 2. Gerak satu arah seperti pintu ini menyerupai kerja engsel. 3. Jadi sendi siku dan lutut termasuk sendi engsel." },
    { q: "Otot yang bekerja tanpa kesadaran dan terdapat pada organ dalam adalah otot ...", options: ["lurik", "polos", "jantung", "rangka"], answer: 1, solution: "1. Organ dalam seperti usus dan pembuluh darah bergerak tanpa perintah sadar. 2. Otot penyusunnya berbentuk gelendong, berinti satu, dan bekerja involunter. 3. Otot dengan ciri tersebut adalah otot polos." },
    { q: "Ciri khas otot jantung adalah ...", options: ["silindris berinti satu dan bekerja sadar", "bercabang dan bekerja tanpa disadari", "gelendong berinti satu di organ dalam", "lurik dan melekat pada rangka"], answer: 1, solution: "1. Jantung harus berdenyut terus-menerus seumur hidup tanpa diperintah sadar. 2. Sel-selnya bercabang dan saling berhubungan agar kontraksi serentak. 3. Jadi ciri khas otot jantung adalah bercabang dan bekerja tanpa disadari." },
    { q: "Sifat otot saat berkontraksi adalah ...", options: ["memanjang dan menipis", "memendek dan menebal", "tetap tidak berubah", "memanjang dan menebal"], answer: 1, solution: "1. Otot hanya dapat menarik, tidak dapat mendorong. 2. Saat menarik (kontraksi), serabut otot memendek. 3. Karena volumenya tetap, otot yang memendek akan menebal." },
    { q: "Kekurangan vitamin D pada anak-anak menyebabkan penyakit ...", options: ["osteoporosis", "rakitis", "artritis", "lordosis"], answer: 1, solution: "1. Vitamin D membantu penyerapan kalsium untuk pembentukan tulang. 2. Anak yang kekurangan vitamin D tulangnya lunak dan mudah bengkok. 3. Kelainan tulang lunak dan bengkok pada anak ini disebut rakitis." },
    { q: "Kelainan tulang belakang yang melengkung ke samping disebut ...", options: ["kifosis", "lordosis", "skoliosis", "artritis"], answer: 2, solution: "1. Kelainan tulang belakang dibedakan menurut arah lengkungannya. 2. Kifosis melengkung ke belakang, lordosis melengkung ke depan. 3. Lengkungan ke samping (kiri-kanan) disebut skoliosis." },
    { q: "Berikut ini fungsi rangka manusia, KECUALI ...", options: ["menegakkan tubuh", "melindungi organ dalam", "tempat melekatnya otot", "menghasilkan energi"], answer: 3, solution: "1. Rangka menegakkan tubuh, melindungi organ dalam seperti otak dan jantung, serta menjadi tempat melekatnya otot. 2. Energi tubuh dihasilkan dari respirasi sel di mitokondria, bukan oleh rangka. 3. Jadi yang bukan fungsi rangka adalah menghasilkan energi." },
    { q: "Tulang rawan (kartilago) pada orang dewasa banyak terdapat pada ...", options: ["ujung tulang pada persendian", "diafisis tulang pipa", "tulang tengkorak", "sumsum tulang"], answer: 0, solution: "1. Tulang rawan bersifat lentur dan licin. 2. Sifat licinnya dibutuhkan agar gesekan antar tulang pada sendi berkurang. 3. Jadi tulang rawan banyak terdapat pada ujung tulang di daerah persendian." },
    { q: "Cara kerja otot bisep dan trisep pada lengan merupakan contoh gerak ...", options: ["sinergis", "antagonis", "involunter", "refleks"], answer: 1, solution: "1. Saat bisep berkontraksi maka trisep berelaksasi, dan sebaliknya. 2. Dua otot yang bekerja berlawanan seperti ini disebut pasangan otot yang berlawanan. 3. Kerja otot yang berlawanan disebut gerak antagonis." },
    { q: "Sel darah yang berfungsi mengangkut oksigen ke seluruh tubuh adalah ...", options: ["eritrosit", "leukosit", "trombosit", "plasma darah"], answer: 0, solution: "1. Oksigen dari paru-paru harus diedarkan ke seluruh jaringan tubuh. 2. Pengangkutnya adalah sel darah merah yang mengandung hemoglobin. 3. Sel darah merah disebut eritrosit." },
    { q: "Hemoglobin di dalam darah berfungsi mengikat ...", options: ["oksigen", "karbon dioksida", "nitrogen", "hidrogen"], answer: 0, solution: "1. Hemoglobin adalah protein berpigmen merah dalam eritrosit. 2. Di paru-paru hemoglobin mengikat oksigen membentuk oksihemoglobin. 3. Jadi fungsi hemoglobin adalah mengikat oksigen." },
    { q: "Sel darah putih yang berperan dalam sistem kekebalan tubuh adalah ...", options: ["eritrosit", "leukosit", "trombosit", "plasma"], answer: 1, solution: "1. Tubuh memerlukan pertahanan terhadap kuman penyakit. 2. Sel darah yang dapat memangsa kuman (fagositosis) dan membentuk antibodi adalah sel darah putih. 3. Sel darah putih disebut leukosit." },
    { q: "Kepingan darah (trombosit) berperan dalam proses ...", options: ["pengangkutan oksigen", "kekebalan tubuh", "pembekuan darah", "pengangkutan sari makanan"], answer: 2, solution: "1. Saat pembuluh darah luka, darah harus segera berhenti mengalir. 2. Trombosit akan pecah dan mengeluarkan enzim yang mengubah fibrinogen menjadi benang fibrin. 3. Benang fibrin menutup luka, sehingga trombosit berperan dalam pembekuan darah." },
    { q: "Orang bergolongan darah O memiliki aglutinin ...", options: ["tidak memiliki aglutinin", "aglutinin alfa saja", "aglutinin beta saja", "aglutinin alfa dan beta"], answer: 3, solution: "1. Golongan darah O tidak memiliki aglutinogen A maupun B pada eritrositnya. 2. Sebagai gantinya, plasma darahnya mengandung kedua jenis aglutinin. 3. Jadi golongan darah O memiliki aglutinin alfa dan beta." },
    { q: "Golongan darah yang dapat mendonorkan darahnya ke semua golongan disebut donor universal, yaitu golongan ...", options: ["A", "B", "AB", "O"], answer: 3, solution: "1. Golongan darah O tidak memiliki aglutinogen A dan B. 2. Karena tidak ada aglutinogen, darah O tidak akan digumpalkan oleh aglutinin resipien. 3. Jadi golongan O disebut donor universal." },
    { q: "Golongan darah yang dapat menerima darah dari semua golongan disebut resipien universal, yaitu golongan ...", options: ["A", "B", "AB", "O"], answer: 2, solution: "1. Golongan darah AB tidak memiliki aglutinin alfa maupun beta dalam plasmanya. 2. Tanpa aglutinin, darah donor golongan apa pun tidak akan digumpalkan. 3. Jadi golongan AB disebut resipien universal." },
    { q: "Pembuluh darah yang membawa darah kaya oksigen dari jantung ke seluruh tubuh adalah ...", options: ["vena kava", "aorta", "vena pulmonalis", "arteri pulmonalis"], answer: 1, solution: "1. Darah kaya oksigen dipompa dari ventrikel kiri jantung. 2. Pembuluh nadi terbesar yang keluar dari ventrikel kiri dan bercabang ke seluruh tubuh adalah pembuluh aorta. 3. Jadi pembuluh tersebut adalah aorta." },
    { q: "Pembuluh darah yang membawa darah dari jantung menuju paru-paru adalah ...", options: ["vena pulmonalis", "arteri pulmonalis", "aorta", "vena kava"], answer: 1, solution: "1. Darah miskin oksigen dari ventrikel kanan harus dibersihkan di paru-paru. 2. Pembuluh yang keluar dari jantung menuju paru-paru disebut arteri, yaitu arteri pulmonalis. 3. Arteri pulmonalis unik karena membawa darah miskin oksigen." },
    { q: "Katup jantung yang memisahkan serambi kiri dan bilik kiri adalah katup ...", options: ["trikuspidalis", "bikuspidalis", "semilunar aorta", "semilunar pulmonalis"], answer: 1, solution: "1. Antara serambi (atrium) dan bilik (ventrikel) terdapat katup agar darah tidak berbalik. 2. Katup di sisi kiri jantung berdaun dua. 3. Katup berdaun dua (bi = dua) disebut katup bikuspidalis atau katup mitral." },
    { q: "Denyut jantung manusia diatur oleh ...", options: ["nodus SA (sinoatrial)", "berkas His", "serabut Purkinje", "katup jantung"], answer: 0, solution: "1. Jantung berdenyut secara otomatis tanpa perintah sadar. 2. Denyut diawali oleh impuls listrik dari segugus sel khusus di serambi kanan. 3. Pusat pembangkit impuls tersebut adalah nodus SA (sinoatrial)." },
    { q: "Tekanan darah normal orang dewasa yang sehat adalah sekitar ...", options: ["120/80 mmHg", "80/120 mmHg", "140/90 mmHg", "100/60 mmHg"], answer: 0, solution: "1. Tekanan darah ditulis sebagai tekanan sistol (bilik berkontraksi) per diastol (bilik relaksasi). 2. Nilai normalnya sekitar 120 untuk sistol dan 80 untuk diastol. 3. Jadi tekanan darah normal adalah 120/80 mmHg." },
    { q: "Penyakit penyumbatan pembuluh darah akibat penumpukan kolesterol disebut ...", options: ["aterosklerosis", "anemia", "hemofilia", "leukemia"], answer: 0, solution: "1. Kolesterol berlebih dapat menempel pada dinding pembuluh darah. 2. Tumpukan plak kolesterol menyempitkan dan mengeraskan pembuluh. 3. Pengerasan dan penyumbatan pembuluh oleh plak disebut aterosklerosis." },
    { q: "Penyakit anemia disebabkan kekurangan ...", options: ["trombosit", "hemoglobin", "leukosit", "plasma darah"], answer: 1, solution: "1. Anemia ditandai dengan tubuh lemas dan pucat karena oksigen kurang. 2. Oksigen diangkut oleh hemoglobin dalam eritrosit. 3. Jadi anemia disebabkan kekurangan hemoglobin (sering karena kurang zat besi)." },
    { q: "Pencernaan makanan secara kimiawi pertama kali terjadi di ...", options: ["mulut", "lambung", "usus halus", "kerongkongan"], answer: 0, solution: "1. Makanan pertama kali masuk melalui mulut. 2. Di mulut terdapat enzim amilase (ptialin) dalam air liur yang mulai mencerna amilum. 3. Jadi pencernaan kimiawi pertama kali terjadi di mulut." },
    { q: "Enzim amilase mengubah amilum menjadi ...", options: ["maltosa", "glukosa", "asam amino", "gliserol"], answer: 0, solution: "1. Amilum adalah polisakarida yang perlu dipecah bertahap. 2. Enzim amilase memecah amilum menjadi disakarida. 3. Disakarida hasil pencernaan amilum oleh amilase adalah maltosa." },
    { q: "Lambung menghasilkan asam ...", options: ["asam klorida (HCl)", "natrium hidroksida", "asam cuka", "enzim amilase"], answer: 0, solution: "1. Lambung perlu suasana asam untuk mengaktifkan enzim pepsin. 2. Suasana asam juga membunuh kuman yang masuk bersama makanan. 3. Asam yang dihasilkan lambung adalah asam klorida (HCl)." },
    { q: "Enzim pepsin yang dihasilkan lambung berfungsi mencerna ...", options: ["protein", "lemak", "karbohidrat", "vitamin"], answer: 0, solution: "1. Pepsin adalah enzim protease yang aktif dalam suasana asam lambung. 2. Enzim protease bekerja memecah molekul protein. 3. Jadi pepsin berfungsi mencerna protein menjadi pepton." },
    { q: "Getah pankreas mengandung enzim ...", options: ["pepsin", "tripsin, amilase, dan lipase", "renin", "laktase saja"], answer: 1, solution: "1. Pankreas menghasilkan getah yang dialirkan ke usus halus. 2. Getah ini harus melengkapi pencernaan karbohidrat, protein, dan lemak. 3. Enzimnya adalah amilase (karbohidrat), tripsin (protein), dan lipase (lemak)." },
    { q: "Struktur usus halus yang memperluas bidang penyerapan sari makanan adalah ...", options: ["vili (jonjot usus)", "enzim pepsin", "getah empedu", "otot polos"], answer: 0, solution: "1. Penyerapan sari makanan harus efisien pada permukaan yang luas. 2. Dinding usus halus berlipat-lipat membentuk tonjolan halus seperti jari. 3. Tonjolan tersebut disebut vili atau jonjot usus yang memperluas penyerapan." },
    { q: "Cairan empedu dihasilkan oleh ...", options: ["hati", "pankreas", "lambung", "usus halus"], answer: 0, solution: "1. Empedu disimpan dalam kantong empedu tetapi bukan dibuat di sana. 2. Organ yang memproduksi empedu dari perombakan hemoglobin adalah hati. 3. Jadi empedu dihasilkan oleh hati." },
    { q: "Fungsi utama cairan empedu dalam pencernaan adalah ...", options: ["mengemulsikan lemak", "mencerna protein", "menyerap vitamin", "menetralkan racun saja"], answer: 0, solution: "1. Lemak berbentuk gumpalan besar sehingga sulit dicerna lipase. 2. Empedu memecah gumpalan lemak menjadi butiran-butiran halus. 3. Proses pemecahan lemak menjadi butiran halus ini disebut emulsifikasi." },
    { q: "Kelompok vitamin yang larut dalam lemak adalah vitamin ...", options: ["B dan C", "A, D, E, dan K", "C saja", "B12 saja"], answer: 1, solution: "1. Vitamin dibedakan menjadi larut air dan larut lemak. 2. Vitamin B kompleks dan C larut dalam air. 3. Vitamin yang larut dalam lemak adalah A, D, E, dan K." },
    { q: "Kekurangan vitamin C dapat menyebabkan penyakit ...", options: ["rabun senja", "skorbut (sariawan dan gusi berdarah)", "beri-beri", "rakitis"], answer: 1, solution: "1. Vitamin C berperan menjaga kesehatan jaringan dan daya tahan tubuh. 2. Kekurangannya membuat gusi mudah berdarah dan luka sulit sembuh. 3. Penyakit kekurangan vitamin C ini disebut skorbut." },
    { q: "Gerakan meremas-remas makanan di kerongkongan menuju lambung disebut gerak ...", options: ["peristaltik", "difusi", "osmosis", "segmentasi"], answer: 0, solution: "1. Makanan harus didorong dari kerongkongan ke lambung. 2. Otot dinding kerongkongan berkontraksi bergelombang dari atas ke bawah. 3. Gerakan meremas bergelombang ini disebut gerak peristaltik." },
    { q: "Sari makanan yang diserap oleh vili usus halus kemudian diangkut oleh ...", options: ["pembuluh darah dan pembuluh limfa", "serabut saraf", "saluran empedu", "ureter"], answer: 0, solution: "1. Vili usus halus kaya akan pembuluh kapiler darah dan pembuluh limfa (lakteal). 2. Asam amino dan glukosa masuk ke kapiler darah, sedangkan asam lemak ke pembuluh limfa. 3. Jadi sari makanan diangkut oleh pembuluh darah dan pembuluh limfa." },
    { q: "Permukaan alveolus yang sangat luas berfungsi untuk ...", options: ["mempercepat difusi gas", "menyaring debu", "menghasilkan lendir", "memompa udara"], answer: 0, solution: "1. Pertukaran O2 dan CO2 di paru-paru terjadi secara difusi. 2. Laju difusi sebanding dengan luas permukaan pertukaran. 3. Jadi permukaan alveolus yang sangat luas berfungsi mempercepat difusi gas." },
    { q: "Urutan saluran pernapasan manusia yang benar adalah ...", options: ["hidung - faring - laring - trakea - bronkus - bronkiolus - alveolus", "hidung - laring - faring - bronkus - trakea - alveolus", "hidung - trakea - faring - laring - bronkiolus - alveolus", "hidung - faring - trakea - bronkiolus - bronkus - alveolus"], answer: 0, solution: "1. Udara masuk lewat hidung lalu ke tenggorokan (faring). 2. Dari faring melewati pangkal tenggorokan (laring) ke batang tenggorokan (trakea). 3. Trakea bercabang menjadi bronkus, lalu bronkiolus, dan berakhir di alveolus." },
    { q: "Mekanisme inspirasi pada pernapasan dada adalah ...", options: ["otot antar tulang rusuk berkontraksi sehingga rongga dada membesar", "diafragma berelaksasi sehingga rongga dada mengecil", "otot perut berkontraksi kuat", "tulang rusuk turun dan rongga dada menyempit"], answer: 0, solution: "1. Inspirasi adalah pemasukan udara yang memerlukan rongga dada membesar. 2. Otot antar tulang rusuk berkontraksi sehingga tulang rusuk terangkat. 3. Terangkatnya tulang rusuk membuat rongga dada membesar dan udara masuk." },
    { q: "Volume udara pernapasan biasa (tidal) orang dewasa sekitar ...", options: ["500 mL", "1500 mL", "3000 mL", "100 mL"], answer: 0, solution: "1. Pernapasan biasa adalah udara yang masuk-keluar tanpa usaha khusus. 2. Volumenya jauh lebih kecil daripada kapasitas total paru-paru. 3. Volume tidal normal orang dewasa sekitar 500 mL." },
    { q: "Udara cadangan ekspirasi adalah udara yang ...", options: ["masih dapat dikeluarkan setelah ekspirasi biasa", "masuk saat inspirasi biasa", "selalu tersisa di paru-paru", "masuk saat inspirasi maksimal"], answer: 0, solution: "1. Setelah menghembuskan napas biasa, paru-paru masih menyimpan udara. 2. Sebagian udara simpanan itu masih bisa dihembuskan dengan usaha kuat. 3. Udara yang masih dapat dikeluarkan setelah ekspirasi biasa disebut udara cadangan ekspirasi (suplementer)." },
    { q: "Difusi oksigen dari alveolus ke kapiler darah terjadi karena ...", options: ["perbedaan tekanan parsial", "pompa jantung", "kontraksi otot dada", "bantuan enzim"], answer: 0, solution: "1. Difusi adalah perpindahan zat dari konsentrasi tinggi ke rendah. 2. Tekanan parsial O2 di alveolus lebih tinggi daripada di kapiler darah. 3. Karena perbedaan tekanan parsial inilah O2 berdifusi ke darah." },
    { q: "Hemoglobin yang telah mengikat oksigen disebut ...", options: ["oksihemoglobin", "karboksihemoglobin", "methemoglobin", "hemosianin"], answer: 0, solution: "1. Hemoglobin di paru-paru mengikat O2. 2. Ikatan Hb dengan O2 membentuk senyawa berwarna merah terang. 3. Senyawa Hb yang mengikat oksigen disebut oksihemoglobin." },
    { q: "Penyakit yang ditandai penyempitan saluran napas sehingga sulit bernapas adalah ...", options: ["asma", "TBC", "influenza", "kanker paru"], answer: 0, solution: "1. Penderita mengalami sesak napas dan bunyi mengi saat kambuh. 2. Hal ini karena otot saluran napas (bronkus) menyempit dan berlendir. 3. Penyakit penyempitan saluran napas tersebut adalah asma." },
    { q: "Kebiasaan merokok dapat menyebabkan penyakit ...", options: ["bronkitis dan emfisema", "asma ringan", "TBC", "pneumonia"], answer: 0, solution: "1. Asap rokok mengandung tar dan zat beracun yang merusak saluran napas. 2. Kerusakan kronis menyebabkan radang bronkus dan rusaknya alveolus. 3. Penyakit akibat rokok tersebut antara lain bronkitis dan emfisema." },
    { q: "Laring pada sistem pernapasan berfungsi sebagai ...", options: ["tempat pita suara", "tempat pertukaran gas", "penyaring udara", "penghasil lendir"], answer: 0, solution: "1. Laring terletak di pangkal tenggorokan setelah faring. 2. Di dalamnya terdapat pita suara yang bergetar saat udara lewat. 3. Jadi laring berfungsi sebagai tempat pita suara." },
    { q: "Epiglotis berfungsi untuk ...", options: ["menutup saluran napas saat menelan", "membuka pita suara", "menyaring debu", "melembapkan udara"], answer: 0, solution: "1. Saat menelan, makanan tidak boleh masuk ke saluran napas. 2. Diperlukan katup yang menutup laring setiap kali menelan. 3. Katup tersebut adalah epiglotis yang menutup saluran napas saat menelan." },
    { q: "Proses pertukaran gas O2 dan CO2 di jaringan tubuh disebut respirasi ...", options: ["eksternal", "internal", "dada", "perut"], answer: 1, solution: "1. Respirasi eksternal adalah pertukaran gas di paru-paru. 2. Pertukaran gas antara kapiler darah dan sel-sel jaringan terjadi di dalam tubuh. 3. Pertukaran gas di tingkat jaringan ini disebut respirasi internal." },
    { q: "Neuron sensorik berfungsi ...", options: ["menghantar impuls dari reseptor ke saraf pusat", "menghantar impuls dari saraf pusat ke efektor", "menghubungkan antar neuron", "mengatur gerak refleks"], answer: 0, solution: "1. Rangsang pertama kali ditangkap oleh reseptor (indera). 2. Impuls dari reseptor harus dibawa menuju otak atau sumsum tulang belakang. 3. Neuron yang membawa impuls dari reseptor ke saraf pusat adalah neuron sensorik." },
    { q: "Bagian neuron yang berfungsi meneruskan impuls ke neuron atau efektor lain adalah ...", options: ["dendrit", "akson", "badan sel", "nukleus"], answer: 1, solution: "1. Dendrit menerima impuls dan meneruskannya ke badan sel. 2. Dari badan sel, impuls harus disalurkan keluar menuju sel berikutnya. 3. Serabut panjang penyalur impuls keluar tersebut adalah akson." },
    { q: "Selubung mielin pada akson berfungsi untuk ...", options: ["memperlambat impuls", "mempercepat jalannya impuls", "memberi makan neuron", "menerima rangsang"], answer: 1, solution: "1. Impuls harus sampai ke tujuan dengan cepat. 2. Selubung mielin bersifat isolator sehingga impuls melompat antar nodus Ranvier. 3. Loncatan impuls ini membuat jalannya impuls jauh lebih cepat." },
    { q: "Gerak refleks pada manusia dikoordinasikan oleh ...", options: ["otak besar", "sumsum tulang belakang", "otak kecil", "sumsum lanjutan"], answer: 1, solution: "1. Gerak refleks seperti menarik tangan dari benda panas terjadi sangat cepat. 2. Impuls tidak sempat diolah di otak, melainkan langsung dibalas. 3. Jalur pintas impuls refleks ini dikoordinasikan oleh sumsum tulang belakang." },
    { q: "Sumsum lanjutan (medula oblongata) berfungsi mengatur ...", options: ["pernapasan dan denyut jantung", "keseimbangan tubuh", "penglihatan", "ingatan dan berpikir"], answer: 0, solution: "1. Pernapasan dan denyut jantung harus berjalan terus tanpa disadari. 2. Pusat pengatur kegiatan tak sadar ini terletak di batang otak bagian bawah. 3. Bagian tersebut adalah sumsum lanjutan (medula oblongata)." },
    { q: "Otak besar (serebrum) merupakan pusat ...", options: ["keseimbangan tubuh", "kesadaran, berpikir, dan ingatan", "denyut jantung", "gerak refleks"], answer: 1, solution: "1. Manusia dapat berpikir, mengingat, dan berkesadaran. 2. Kegiatan tingkat tinggi ini diatur oleh bagian otak yang paling besar. 3. Bagian tersebut adalah otak besar (serebrum)." },
    { q: "Pulau Langerhans yang menghasilkan hormon insulin terdapat pada ...", options: ["pankreas", "hati", "tiroid", "adrenal"], answer: 0, solution: "1. Insulin adalah hormon pengatur gula darah. 2. Hormon ini dihasilkan oleh sekelompok sel khusus berbentuk pulau-pulau. 3. Kelompok sel pulau Langerhans tersebut terdapat pada pankreas." },
    { q: "Hormon insulin berfungsi untuk ...", options: ["menaikkan kadar gula darah", "menurunkan kadar gula darah", "menaikkan tekanan darah", "memacu pertumbuhan tulang"], answer: 1, solution: "1. Setelah makan, kadar glukosa darah naik. 2. Insulin memerintahkan sel mengambil glukosa dan hati menyimpannya sebagai glikogen. 3. Akibatnya kadar gula darah turun, jadi insulin berfungsi menurunkan gula darah." },
    { q: "Kekurangan hormon insulin menyebabkan penyakit ...", options: ["diabetes melitus", "gondok", "kretinisme", "anemia"], answer: 0, solution: "1. Tanpa insulin yang cukup, glukosa tidak dapat masuk ke sel. 2. Glukosa menumpuk di darah dan terbuang melalui urine. 3. Penyakit gula darah tinggi ini disebut diabetes melitus (kencing manis)." },
    { q: "Hormon adrenalin dihasilkan oleh kelenjar ...", options: ["adrenal (anak ginjal)", "tiroid", "pankreas", "hipofisis"], answer: 0, solution: "1. Saat terkejut atau takut, jantung berdebar dan tubuh siaga. 2. Keadaan siaga ini dipicu hormon adrenalin. 3. Adrenalin dihasilkan oleh kelenjar adrenal yang menempel pada ginjal." },
    { q: "Kelebihan hormon tiroksin dapat menyebabkan ...", options: ["gondok", "hipertiroidisme (jantung berdebar dan berat badan turun)", "diabetes melitus", "kretinisme"], answer: 1, solution: "1. Tiroksin mengatur laju metabolisme tubuh. 2. Jika berlebihan, metabolisme berjalan terlalu cepat: jantung berdebar dan berat badan turun. 3. Keadaan kelebihan tiroksin ini disebut hipertiroidisme." },
    { q: "Kekurangan unsur yodium dalam makanan dapat menyebabkan ...", options: ["gondok", "diabetes", "anemia", "rakitis"], answer: 0, solution: "1. Yodium adalah bahan baku pembentukan hormon tiroksin. 2. Kekurangan yodium membuat kelenjar tiroid membesar karena bekerja keras. 3. Pembengkakan kelenjar tiroid di leher ini disebut gondok." },
    { q: "Bagian mata yang berfungsi mengatur banyaknya cahaya yang masuk adalah ...", options: ["retina", "iris", "kornea", "lensa"], answer: 1, solution: "1. Cahaya yang terlalu banyak menyilaukan, yang terlalu sedikit membuat gelap. 2. Diperlukan diafragma yang dapat membuka-menutup seperti pada kamera. 3. Bagian mata yang mengatur bukaan cahaya (pupil) adalah iris." },
    { q: "Bayangan benda yang dilihat mata jatuh pada ...", options: ["kornea", "lensa", "retina", "iris"], answer: 2, solution: "1. Cahaya dari benda dibiaskan oleh kornea dan lensa mata. 2. Berkas cahaya harus ditangkap oleh lapisan peka cahaya. 3. Lapisan peka cahaya berisi sel batang dan kerucut itu adalah retina." },
    { q: "Bagian telinga yang berfungsi menjaga keseimbangan tubuh adalah ...", options: ["koklea", "kanalis semisirkularis", "gendang telinga", "tulang martil"], answer: 1, solution: "1. Telinga tidak hanya untuk mendengar tetapi juga menjaga keseimbangan. 2. Di telinga dalam terdapat tiga saluran setengah lingkaran berisi cairan. 3. Saluran setengah lingkaran (kanalis semisirkularis) inilah penjaga keseimbangan." },
    { q: "Sel Schwann pada sistem saraf berfungsi ...", options: ["membentuk selubung mielin", "menerima impuls dari dendrit", "menghantar impuls ke otot", "memproduksi neurotransmiter"], answer: 0, solution: "1. Akson neuron besar dilindungi selubung lemak berlapis. 2. Selubung tersebut dibentuk oleh sel-sel khusus yang melilit akson. 3. Sel pembentuk selubung mielin ini disebut sel Schwann." },
    { q: "Satu sel spermatogonium yang mengalami spermatogenesis menghasilkan ...", options: ["1 spermatozoa", "2 spermatozoa", "4 spermatozoa", "8 spermatozoa"], answer: 2, solution: "1. Spermatogenesis mencakup pembelahan mitosis lalu meiosis. 2. Meiosis dari satu sel diploid menghasilkan 4 sel haploid. 3. Keempat sel haploid berkembang menjadi 4 spermatozoa." },
    { q: "Satu sel oogonium yang mengalami oogenesis menghasilkan ovum fungsional sebanyak ...", options: ["1", "2", "3", "4"], answer: 0, solution: "1. Oogenesis juga melalui meiosis yang menghasilkan 4 sel haploid. 2. Namun pembelahan sitoplasmanya tidak merata sehingga hanya satu sel yang besar. 3. Jadi hanya dihasilkan 1 ovum fungsional dan 3 badan polar." },
    { q: "Hormon testosteron pada pria dihasilkan oleh ...", options: ["testis", "ovarium", "kelenjar prostat", "hipofisis"], answer: 0, solution: "1. Ciri kelamin sekunder pria seperti suara berat dan kumis dipicu hormon. 2. Hormon kelamin pria (androgen) yang utama adalah testosteron. 3. Testosteron dihasilkan oleh testis." },
    { q: "Hormon estrogen dan progesteron pada wanita dihasilkan oleh ...", options: ["testis", "ovarium", "plasenta saja", "kelenjar susu"], answer: 1, solution: "1. Ciri kelamin sekunder wanita dan siklus menstruasi diatur hormon. 2. Hormon kelamin wanita yang utama adalah estrogen dan progesteron. 3. Keduanya dihasilkan oleh ovarium (indung telur)." },
    { q: "Tahapan perkembangan embrio yang berbentuk bola padat disebut ...", options: ["morula", "blastula", "gastrula", "zigot"], answer: 0, solution: "1. Setelah fertilisasi, zigot membelah berkali-kali. 2. Hasil pembelahan awal berupa gumpalan sel padat menyerupai buah murbei. 3. Tahap bola padat ini disebut morula." },
    { q: "Zigot hasil fertilisasi berkembang menjadi embrio di dalam ...", options: ["ovarium", "uterus (rahim)", "tuba falopi", "vagina"], answer: 1, solution: "1. Zigot bergerak dari tuba falopi menuju tempat implantasi. 2. Embrio memerlukan tempat yang kaya pembuluh darah untuk tumbuh. 3. Tempat tersebut adalah uterus (rahim)." },
    { q: "Lama masa kehamilan manusia normal adalah sekitar ...", options: ["6 bulan", "9 bulan", "12 bulan", "3 bulan"], answer: 1, solution: "1. Janin manusia memerlukan waktu untuk berkembang sempurna. 2. Dihitung dari hari pertama haid terakhir, kehamilan berlangsung sekitar 280 hari. 3. Jadi lama kehamilan normal sekitar 9 bulan." },
    { q: "Siklus menstruasi normal rata-rata berlangsung selama ...", options: ["14 hari", "21 hari", "28 hari", "35 hari"], answer: 2, solution: "1. Menstruasi berkaitan dengan siklus pematangan sel telur. 2. Sejak hari pertama haid hingga haid berikutnya pada umumnya sebulan. 3. Rata-rata siklus menstruasi normal adalah 28 hari." },
    { q: "Alat kontrasepsi permanen pada pria adalah ...", options: ["vasektomi", "tubektomi", "IUD", "kondom"], answer: 0, solution: "1. Kontrasepsi permanen memutus saluran reproduksi melalui operasi. 2. Pada pria, saluran yang diputus adalah vas deferens (saluran sperma). 3. Operasi pemutusan vas deferens disebut vasektomi." },
    { q: "Berikut ini penyakit menular seksual yang disebabkan oleh bakteri adalah ...", options: ["sifilis", "AIDS", "herpes", "hepatitis B"], answer: 0, solution: "1. AIDS disebabkan virus HIV, herpes oleh virus herpes, hepatitis B oleh virus. 2. Sifilis (raja singa) disebabkan oleh bakteri Treponema pallidum. 3. Jadi penyakit menular seksual akibat bakteri adalah sifilis." },
    { q: "Ovulasi adalah peristiwa ...", options: ["pelepasan sel telur dari ovarium", "pembentukan sel sperma", "pembuahan sel telur", "luruhnya dinding rahim"], answer: 0, solution: "1. Setiap siklus, satu sel telur matang di ovarium. 2. Sel telur yang matang harus dikeluarkan agar bisa dibuahi. 3. Pelepasan sel telur (ovum) dari ovarium ini disebut ovulasi." },
    { q: "Fungsi plasenta (ari-ari) selama kehamilan adalah ...", options: ["pertukaran zat antara ibu dan janin", "memproduksi sel sperma", "tempat terjadinya fertilisasi", "menghasilkan ASI"], answer: 0, solution: "1. Janin tidak dapat makan dan bernapas sendiri. 2. Janin memperoleh oksigen dan nutrisi dari darah ibu melalui suatu organ penghubung. 3. Organ penghubung untuk pertukaran zat ibu-janin ini adalah plasenta." },
    { q: "Nefron adalah ...", options: ["unit fungsional terkecil ginjal", "lapisan luar ginjal", "pembuluh darah ginjal", "kelenjar pada ginjal"], answer: 0, solution: "1. Ginjal tersusun atas jutaan struktur mikroskopis yang bekerja sama. 2. Setiap struktur mampu melakukan filtrasi, reabsorpsi, dan augmentasi sendiri. 3. Struktur terkecil pelaksana fungsi ginjal ini disebut nefron." },
    { q: "Urutan proses pembentukan urine yang benar adalah ...", options: ["filtrasi - reabsorpsi - augmentasi", "reabsorpsi - filtrasi - augmentasi", "augmentasi - filtrasi - reabsorpsi", "filtrasi - augmentasi - reabsorpsi"], answer: 0, solution: "1. Darah pertama-tama disaring di glomerulus menghasilkan urine primer. 2. Zat yang masih berguna diserap kembali ke darah. 3. Terakhir zat sisa ditambahkan ke urine, sehingga urutannya filtrasi - reabsorpsi - augmentasi." },
    { q: "Proses filtrasi (penyaringan darah) pada ginjal terjadi di ...", options: ["glomerulus", "tubulus kontortus proksimal", "lengkung Henle", "tubulus kolektivus"], answer: 0, solution: "1. Filtrasi adalah penyaringan darah bertekanan tinggi. 2. Anyaman kapiler darah tempat penyaringan ini berlangsung disebut glomerulus. 3. Jadi filtrasi terjadi di glomerulus." },
    { q: "Proses reabsorpsi (penyerapan kembali) pada ginjal terjadi di ...", options: ["glomerulus", "tubulus kontortus proksimal", "tubulus kolektivus", "pelvis ginjal"], answer: 1, solution: "1. Urine primer masih mengandung zat berguna seperti glukosa. 2. Zat-zat tersebut diserap kembali ke pembuluh darah di bagian tubulus pertama. 3. Bagian tersebut adalah tubulus kontortus proksimal." },
    { q: "Zat-zat yang masih direabsorpsi oleh tubulus ginjal antara lain ...", options: ["urea", "glukosa dan asam amino", "kreatinin", "racun"], answer: 1, solution: "1. Urine primer mengandung glukosa, asam amino, ion, urea, dan air. 2. Glukosa dan asam amino masih sangat dibutuhkan tubuh sehingga tidak boleh terbuang. 3. Jadi zat yang direabsorpsi seluruhnya antara lain glukosa dan asam amino." },
    { q: "Kelenjar keringat mengekskresikan ...", options: ["air dan garam (keringat)", "urea pekat", "minyak", "hormon"], answer: 0, solution: "1. Saat kepanasan tubuh mengeluarkan cairan melalui kulit. 2. Cairan tersebut sebagian besar air ditambah garam-garam mineral. 3. Jadi kelenjar keringat mengekskresikan air dan garam berupa keringat." },
    { q: "Hati berperan sebagai organ ekskresi dengan mengeluarkan ...", options: ["urea dan bilirubin", "urine", "keringat", "karbon dioksida"], answer: 0, solution: "1. Hati merombak amonia beracun menjadi urea. 2. Hati juga merombak hemoglobin tua menjadi bilirubin yang dibuang lewat empedu. 3. Jadi zat ekskresi dari hati adalah urea dan bilirubin." },
    { q: "Paru-paru berperan sebagai organ ekskresi dengan mengeluarkan ...", options: ["CO2 dan uap air", "urea", "garam", "empedu"], answer: 0, solution: "1. Sisa respirasi sel adalah karbon dioksida. 2. CO2 diangkut darah ke paru-paru dan dihembuskan bersama uap air. 3. Jadi paru-paru mengekskresikan CO2 dan uap air." },
    { q: "Gangguan ginjal akibat peradangan pada nefron disebut ...", options: ["nefritis", "batu ginjal", "gagal ginjal", "diabetes insipidus"], answer: 0, solution: "1. Infeksi bakteri dapat menyerang bagian penyaring ginjal. 2. Peradangan pada nefron (terutama glomerulus) mengganggu penyaringan. 3. Radang nefron ini disebut nefritis." },
    { q: "Tindakan cuci darah pada penderita gagal ginjal disebut ...", options: ["hemodialisis", "transfusi darah", "kemoterapi", "imunisasi"], answer: 0, solution: "1. Ginjal yang gagal tidak dapat menyaring darah. 2. Darah penderita harus disaring dengan mesin di luar tubuh. 3. Penyaringan darah menggunakan mesin ini disebut hemodialisis." },
    { q: "Antibodi dalam tubuh dihasilkan oleh ...", options: ["limfosit B", "limfosit T", "neutrofil", "monosit"], answer: 0, solution: "1. Saat antigen masuk, tubuh membentuk protein pelawan khusus. 2. Protein pelawan (antibodi) diproduksi oleh sel limfosit tertentu. 3. Sel penghasil antibodi adalah limfosit B." },
    { q: "Proses fagositosis (pemangsaan kuman) dilakukan oleh ...", options: ["neutrofil dan makrofag", "limfosit B", "eritrosit", "trombosit"], answer: 0, solution: "1. Kuman yang masuk tubuh dapat ditelan langsung oleh sel darah putih. 2. Sel yang bertugas menelan dan mencerna kuman adalah neutrofil dan makrofag. 3. Proses penelanan kuman ini disebut fagositosis." },
    { q: "Pemberian vaksin bertujuan membentuk kekebalan ...", options: ["aktif buatan", "pasif buatan", "aktif alami", "pasif alami"], answer: 0, solution: "1. Vaksin berisi antigen yang dilemahkan atau dimatikan. 2. Tubuh dirangsang membentuk antibodinya sendiri terhadap antigen tersebut. 3. Kekebalan yang dibuat tubuh sendiri karena intervensi manusia disebut kekebalan aktif buatan." },
    { q: "Kekebalan yang diperoleh bayi dari ASI termasuk kekebalan ...", options: ["aktif buatan", "pasif alami", "aktif alami", "pasif buatan"], answer: 1, solution: "1. ASI mengandung antibodi siap pakai dari ibu. 2. Bayi tidak memproduksi sendiri, hanya menerima antibodi jadi secara alamiah. 3. Kekebalan berupa antibodi jadi yang diperoleh alami ini disebut kekebalan pasif alami." },
    { q: "Antigen adalah ...", options: ["zat asing pemicu pembentukan antibodi", "sel darah putih", "protein plasma darah", "antibodi itu sendiri"], answer: 0, solution: "1. Sistem imun bereaksi terhadap zat yang dianggap asing oleh tubuh. 2. Zat asing tersebut memicu limfosit membentuk antibodi. 3. Jadi antigen adalah zat asing pemicu pembentukan antibodi." },
    { q: "Alergi merupakan reaksi ...", options: ["berlebihan sistem imun terhadap antigen", "kekurangan antibodi", "infeksi bakteri", "keracunan makanan"], answer: 0, solution: "1. Pada alergi, tubuh bereaksi terhadap zat yang sebenarnya tidak berbahaya seperti debu. 2. Sistem imun memberikan respons yang terlalu kuat terhadap antigen tersebut. 3. Jadi alergi adalah reaksi berlebihan sistem imun terhadap antigen." },
    { q: "Kelenjar timus berperan dalam ...", options: ["pematangan limfosit T", "pembentukan eritrosit", "fagositosis kuman", "produksi antibodi"], answer: 0, solution: "1. Limfosit T adalah sel imun penting untuk kekebalan seluler. 2. Limfosit T yang belum dewasa harus dimatangkan di suatu kelenjar. 3. Kelenjar tempat pematangan limfosit T adalah kelenjar timus." },
    { q: "Tanda-tanda peradangan (inflamasi) adalah ...", options: ["bengkak, merah, panas, dan nyeri", "pucat dan dingin", "kebas dan kesemutan", "gatal saja"], answer: 0, solution: "1. Saat jaringan luka, pembuluh darah melebar dan sel imun berdatangan. 2. Akibatnya daerah luka membengkak, memerah, terasa panas, dan nyeri. 3. Jadi tanda peradangan adalah bengkak, merah, panas, dan nyeri." },
    { q: "Pertumbuhan primer pada tumbuhan terjadi di ...", options: ["meristem apikal", "kambium", "meristem interkalar saja", "floem"], answer: 0, solution: "1. Pertumbuhan primer adalah pertambahan panjang akar dan batang. 2. Pemanjangan ini berpusat pada titik tumbuh di ujung akar dan ujung batang. 3. Jaringan titik tumbuh di ujung disebut meristem apikal." },
    { q: "Hormon auksin berperan dalam ...", options: ["pemanjangan sel dan dominansi apikal", "pematangan buah", "dormansi biji", "penutupan stomata"], answer: 0, solution: "1. Auksin banyak dihasilkan di ujung batang (koleoptil). 2. Auksin memacu pemanjangan sel sehingga batang tumbuh ke atas dan menghambat tunas lateral. 3. Jadi auksin berperan dalam pemanjangan sel dan dominansi apikal." },
    { q: "Hormon giberelin berperan dalam ...", options: ["pematangan buah", "perkecambahan dan pembungaan", "dormansi biji", "gugurnya daun"], answer: 1, solution: "1. Biji yang dorman perlu dirangsang agar berkecambah. 2. Giberelin memicu aktivitas enzim sehingga cadangan makanan dipecah dan tunas tumbuh. 3. Jadi giberelin berperan dalam perkecambahan dan pembungaan." },
    { q: "Hormon yang menghambat pertumbuhan dan menyebabkan dormansi biji adalah ...", options: ["auksin", "asam absisat", "giberelin", "sitokinin"], answer: 1, solution: "1. Pada musim kering, tumbuhan perlu menghentikan pertumbuhan. 2. Diperlukan hormon yang bersifat menghambat sebagai lawan auksin dan giberelin. 3. Hormon penghambat pertumbuhan dan penyebab dormansi ini adalah asam absisat." },
    { q: "Gas etilen pada tumbuhan berperan dalam ...", options: ["pematangan buah", "pembelahan sel", "fotosintesis", "penyerapan air"], answer: 0, solution: "1. Buah yang diperam dengan karbit cepat matang. 2. Karbit menghasilkan gas yang sama dengan gas alami pematang buah. 3. Gas pematang buah tersebut adalah etilen." },
    { q: "Gerak ujung batang tumbuhan mengikuti arah datangnya cahaya disebut ...", options: ["fototropisme", "geotropisme", "hidrotropisme", "kemotropisme"], answer: 0, solution: "1. Tumbuhan dalam ruangan membengkokkan batangnya ke arah jendela. 2. Gerak tumbuh sebagai respons terhadap rangsang cahaya memiliki nama khusus. 3. Gerak mengikuti arah cahaya disebut fototropisme." },
    { q: "Gerak tumbuh akar menuju sumber air disebut ...", options: ["hidrotropisme", "fototropisme", "tigmotropisme", "nasti"], answer: 0, solution: "1. Akar tumbuhan selalu tumbuh ke daerah yang lembap. 2. Gerak tumbuh sebagai respons terhadap rangsang air memiliki nama khusus. 3. Gerak akar menuju air disebut hidrotropisme." },
    { q: "Gerak menutupnya daun putri malu saat disentuh disebut ...", options: ["fototropisme", "seismonasti", "kemotaksis", "geotropisme"], answer: 1, solution: "1. Daun putri malu menutup tidak peduli dari arah mana disentuh. 2. Gerak yang arahnya tidak dipengaruhi arah rangsang disebut gerak nasti. 3. Nasti akibat sentuhan disebut seismonasti (tigmonasti)." },
    { q: "Berikut ini yang merupakan faktor eksternal pertumbuhan tumbuhan adalah ...", options: ["gen", "hormon", "cahaya", "enzim"], answer: 2, solution: "1. Faktor internal berasal dari dalam tumbuhan seperti gen dan hormon. 2. Faktor eksternal berasal dari lingkungan sekitar tumbuhan. 3. Cahaya, air, suhu, dan nutrisi adalah faktor eksternal, sedangkan gen, hormon, dan enzim bersifat internal." },
    { q: "Perkecambahan tipe epigeal, yaitu kotiledon terangkat ke atas tanah, contohnya pada ...", options: ["kacang hijau", "jagung", "kacang kapri", "padi"], answer: 0, solution: "1. Pada perkecambahan epigeal, hipokotil memanjang sehingga kotiledon terangkat. 2. Tumbuhan berbiji dikotil seperti kacang-kacangan umumnya bertipe ini. 3. Contohnya adalah kacang hijau (dan kedelai)." },
    { q: "Perkecambahan tipe hipogeal, yaitu kotiledon tetap di bawah tanah, contohnya pada ...", options: ["kacang hijau", "jagung", "kedelai", "kacang tanah"], answer: 1, solution: "1. Pada perkecambahan hipogeal, epikotil yang memanjang sehingga kotiledon tertinggal. 2. Tipe ini banyak ditemukan pada tumbuhan monokotil. 3. Contohnya adalah jagung (dan kacang kapri)." },
    { q: "Pertumbuhan sekunder yang menyebabkan batang tumbuhan membesar terjadi pada ...", options: ["kambium", "meristem apikal", "ujung akar", "tunas lateral"], answer: 0, solution: "1. Batang tumbuhan dikotil bertambah besar (diameternya), bukan hanya panjang. 2. Penambahan diameter dilakukan oleh jaringan meristem lateral. 3. Meristem lateral tersebut adalah kambium." },
    { q: "Bunyi Hukum Mendel I (hukum segregasi) adalah ...", options: ["pasangan alel memisah saat pembentukan gamet", "alel gen berbeda berpasangan bebas", "sifat dominan selalu muncul", "kromosom selalu berpasangan"], answer: 0, solution: "1. Setiap individu membawa sepasang alel untuk tiap sifat. 2. Saat membentuk gamet, pasangan alel tersebut harus berpisah. 3. Prinsip pemisahan pasangan alel ini adalah Hukum Mendel I (segregasi)." },
    { q: "Bunyi Hukum Mendel II (hukum asortasi bebas) adalah ...", options: ["alel memisah saat gamet", "alel dari gen berbeda berpasangan secara bebas", "gen-gen selalu terpaut", "terjadi mutasi gen"], answer: 1, solution: "1. Individu memiliki banyak pasangan gen untuk sifat berbeda. 2. Pada pembentukan gamet, alel dari gen yang berbeda tidak saling memengaruhi. 3. Prinsip perpasangan bebas ini adalah Hukum Mendel II (asortasi bebas)." },
    { q: "Genotipe adalah ...", options: ["sifat yang tampak dari luar", "susunan gen dalam kromosom", "jumlah kromosom", "jenis protein"], answer: 1, solution: "1. Sifat yang tampak dari luar disebut fenotipe, misalnya warna bunga. 2. Sifat tersebut ditentukan oleh susunan pasangan gen yang tidak tampak. 3. Susunan gen dalam kromosom ini disebut genotipe." },
    { q: "Tujuan dilakukannya uji silang (test cross) adalah ...", options: ["mengetahui genotipe individu yang bersifat dominan", "menghasilkan varietas unggul baru", "mengetahui jenis kelamin individu", "menggandakan jumlah kromosom"], answer: 0, solution: "1. Individu berfenotipe dominan dapat bergenotipe homozigot atau heterozigot. 2. Untuk membedakannya, individu tersebut disilangkan dengan yang resesif. 3. Jadi tujuan test cross adalah mengetahui genotipe individu bersifat dominan." },
    { q: "Uji silang (test cross) dilakukan dengan menyilangkan individu yang diuji dengan individu bergenotipe ...", options: ["homozigot dominan", "homozigot resesif", "heterozigot", "hemizigot"], answer: 1, solution: "1. Test cross memerlukan pasangan yang genotipenya sudah pasti. 2. Individu resesif pasti bergenotipe homozigot resesif (aa). 3. Jadi test cross menyilangkan individu uji dengan homozigot resesif." },
    { q: "Penyakit hemofilia terpaut pada kromosom ...", options: ["X", "Y", "autosom", "mitokondria"], answer: 0, solution: "1. Hemofilia (darah sukar membeku) lebih banyak diderita laki-laki. 2. Pola pewarisan yang menyerang laki-laki ini khas untuk gen pada kromosom kelamin. 3. Gen hemofilia terpaut pada kromosom X dan bersifat resesif." },
    { q: "Seorang pria buta warna (XbY) menikah dengan wanita berpenglihatan normal homozigot (XBXB). Semua anak perempuan mereka akan ...", options: ["buta warna", "berpenglihatan normal tetapi carrier buta warna", "berpenglihatan normal homozigot", "buta warna sebagian"], answer: 1, solution: "1. Anak perempuan mendapat kromosom X dari ayah (Xb) dan dari ibu (XB). 2. Genotipe semua anak perempuan adalah XBXb. 3. Karena B dominan, mereka berpenglihatan normal tetapi membawa gen buta warna (carrier)." },
    { q: "Golongan darah manusia ditentukan oleh alel ganda ...", options: ["IA, IB, dan IO", "A, B, dan O", "AA, BB, dan OO", "IA dan IB saja"], answer: 0, solution: "1. Golongan darah A, B, AB, dan O ditentukan oleh lebih dari dua alel. 2. Alel-alel tersebut menempati lokus yang sama pada kromosom. 3. Alel ganda golongan darah adalah IA, IB, dan IO." },
    { q: "Genotipe golongan darah AB adalah ...", options: ["IAIA", "IBIB", "IAIB", "IOIO"], answer: 2, solution: "1. Golongan darah AB memiliki aglutinogen A dan B sekaligus. 2. Kedua aglutinogen muncul karena alel IA dan IB bersifat kodominan. 3. Jadi genotipe golongan darah AB adalah IAIB." },
    { q: "Seorang ibu bergolongan darah B heterozigot (IBIO) menikah dengan ayah bergolongan darah O (IOIO). Kemungkinan golongan darah anak-anaknya adalah ...", options: ["A atau B", "A atau O", "B atau O", "AB"], answer: 2, solution: "1. Ibu menghasilkan gamet IB dan IO, ayah hanya menghasilkan gamet IO. 2. Pasangannya menjadi IBIO (golongan B) dan IOIO (golongan O). 3. Jadi kemungkinan anak bergolongan darah B atau O." },
    { q: "Persilangan bunga pukul empat merah (MM) dengan putih (mm) yang bersifat dominansi tidak sempurna menghasilkan ...", options: ["100% merah", "100% merah muda", "100% putih", "50% merah : 50% putih"], answer: 1, solution: "1. Pada dominansi tidak sempurna, alel dominan tidak menutupi penuh alel resesif. 2. Genotipe heterozigot (Mm) menampilkan sifat antara kedua induk. 3. Jadi seluruh keturunan (100% Mm) berbunga merah muda." },
    { q: "Pada peristiwa dominansi tidak sempurna, persilangan Mm x Mm menghasilkan perbandingan fenotipe ...", options: ["3 : 1", "9 : 3 : 3 : 1", "1 : 2 : 1", "1 : 1"], answer: 2, solution: "1. Persilangan Mm x Mm menghasilkan genotipe MM, Mm, Mm, dan mm. 2. Karena dominansi tidak sempurna, tiap genotipe menampilkan fenotipe berbeda. 3. Perbandingannya 1 merah : 2 merah muda : 1 putih, yaitu 1 : 2 : 1." },
    { q: "Epistasis adalah peristiwa ...", options: ["satu gen menutupi ekspresi gen lain", "gen-gen yang terpaut", "adanya alel ganda", "pindah silang kromosom"], answer: 0, solution: "1. Terkadang suatu sifat ditentukan oleh interaksi dua gen berbeda. 2. Gen yang satu dapat menutupi atau menghambat ekspresi gen lainnya. 3. Peristiwa satu gen menutupi ekspresi gen lain disebut epistasis." },
    { q: "Jumlah autosom pada sel tubuh manusia adalah ...", options: ["46", "44", "23", "22"], answer: 1, solution: "1. Sel tubuh manusia memiliki 46 kromosom atau 23 pasang. 2. Dari 23 pasang tersebut, 1 pasang adalah kromosom kelamin (gonosom). 3. Sisanya 22 pasang (44 buah) adalah autosom." },
    { q: "Kariotipe normal pria ditulis ...", options: ["44A + XX", "44A + XY", "46A + XY", "22A + XY"], answer: 1, solution: "1. Kariotipe pria terdiri atas 44 autosom dan sepasang kromosom kelamin. 2. Pasangan kromosom kelamin pria berbeda, yaitu X dan Y. 3. Jadi kariotipe pria normal ditulis 44A + XY." },
    { q: "Sindrom Down disebabkan oleh ...", options: ["trisomi kromosom 21", "monosomi kromosom X", "trisomi kromosom kelamin XXY", "delesi kromosom 5"], answer: 0, solution: "1. Sindrom Down adalah kelainan jumlah kromosom bawaan. 2. Penderitanya memiliki 47 kromosom karena satu kromosom berlebih. 3. Kelebihan tersebut terjadi pada kromosom nomor 21 (trisomi 21)." },
    { q: "Sindrom Turner memiliki kariotipe ...", options: ["44A + XO", "44A + XXY", "44A + XX", "44A + XXX"], answer: 0, solution: "1. Sindrom Turner hanya diderita wanita dengan 45 kromosom. 2. Kekurangan satu kromosom terjadi pada kromosom kelamin. 3. Kariotipenya 44A + XO (hanya satu kromosom X)." },
    { q: "Sindrom Klinefelter memiliki kariotipe ...", options: ["44A + XO", "44A + XXY", "44A + XYY", "44A + XXX"], answer: 1, solution: "1. Sindrom Klinefelter diderita pria dengan 47 kromosom. 2. Kelebihan satu kromosom X pada kromosom kelaminnya. 3. Kariotipenya 44A + XXY." },
    { q: "Gula penyusun DNA adalah gula ...", options: ["ribosa", "deoksiribosa", "glukosa", "fruktosa"], answer: 1, solution: "1. DNA tersusun atas gugus fosfat, basa nitrogen, dan gula pentosa. 2. Gula DNA kekurangan satu atom oksigen dibanding gula RNA. 3. Gula pentosa DNA ini disebut deoksiribosa." },
    { q: "Sifat yang hanya diwariskan dari ayah ke anak laki-laki (terpaut kromosom Y) disebut pola ...", options: ["holandrik", "terpaut X dominan", "autosomal resesif", "kodominan"], answer: 0, solution: "1. Kromosom Y hanya dimiliki laki-laki dan diwariskan ayah ke anak laki-laki. 2. Sifat pada kromosom Y tidak pernah muncul pada anak perempuan. 3. Pola pewarisan khusus melalui kromosom Y ini disebut holandrik." },
    { q: "Jumlah macam gamet yang dihasilkan individu bergenotipe AaBb adalah ...", options: ["2", "3", "4", "8"], answer: 2, solution: "1. Setiap pasangan alel heterozigot menghasilkan 2 macam gamet. 2. Individu AaBb memiliki 2 pasang alel heterozigot. 3. Jumlah macam gamet = 2 x 2 = 4, yaitu AB, Ab, aB, dan ab." },
    { q: "Persilangan individu bergenotipe AABb dengan aabb akan menghasilkan keturunan bergenotipe ...", options: ["AaBb dan Aabb", "AABb dan AaBb", "aaBb dan aabb", "AaBb saja"], answer: 0, solution: "1. Individu AABb menghasilkan gamet AB dan Ab, sedangkan aabb hanya menghasilkan gamet ab. 2. Pasangan gametnya: AB + ab = AaBb dan Ab + ab = Aabb. 3. Jadi keturunannya bergenotipe AaBb dan Aabb." },
    { q: "Sebelum Darwin, teori evolusi dikemukakan oleh Lamarck yang berpendapat bahwa ...", options: ["sifat yang diperoleh selama hidup diwariskan ke keturunan", "spesies tidak pernah berubah", "evolusi terjadi karena seleksi alam", "perubahan karena mutasi acak"], answer: 0, solution: "1. Lamarck mengamati organ yang sering dipakai tampak berkembang. 2. Ia menyimpulkan sifat yang diperoleh (acquired characters) selama hidup diwariskan. 3. Teori ini dikenal sebagai use and disuse." },
    { q: "Buku yang memuat teori evolusi Darwin berjudul ...", options: ["On the Origin of Species", "Philosophie Zoologique", "The Descent of Man saja", "Principles of Geology"], answer: 0, solution: "1. Darwin mempublikasikan gagasannya setelah pelayaran dengan kapal Beagle. 2. Buku tersebut menjelaskan asal-usul spesies melalui seleksi alam. 3. Judulnya adalah On the Origin of Species (1859)." },
    { q: "Menurut teori seleksi alam Darwin, individu yang bertahan hidup adalah yang ...", options: ["paling kuat saja", "paling sesuai dengan lingkungannya", "paling besar", "paling cepat"], answer: 1, solution: "1. Lingkungan menyeleksi individu yang hidup di dalamnya. 2. Bukan yang terkuat, melainkan yang paling cocok (fit) dengan lingkungan. 3. Prinsip ini disebut survival of the fittest." },
    { q: "Fosil adalah ...", options: ["sisa makhluk hidup yang membatu", "makhluk hidup purba yang masih hidup", "batuan biasa", "jejak kaki hewan modern"], answer: 0, solution: "1. Sisa organisme purba dapat terawetkan dalam lapisan batuan. 2. Jaringan yang tertimbun mengalami mineralisasi selama jutaan tahun. 3. Sisa makhluk hidup yang membatu ini disebut fosil." },
    { q: "Tulang ekor manusia merupakan contoh organ ...", options: ["vestigial (sisa)", "homolog", "analog", "vital"], answer: 0, solution: "1. Manusia memiliki tulang ekor kecil yang tidak berfungsi penting. 2. Organ yang menyusut dan kehilangan fungsi asalnya disebut organ sisa. 3. Organ sisa evolusi ini disebut organ vestigial (rudimenter)." },
    { q: "Tungkai depan tikus tanah (untuk menggali) dan kelelawar (untuk terbang) merupakan organ ...", options: ["homolog", "analog", "vestigial", "tidak berhubungan"], answer: 0, solution: "1. Kedua tungkai berasal dari struktur dasar kerangka mamalia yang sama. 2. Meskipun fungsinya berbeda (menggali vs terbang), asal usulnya sama. 3. Organ yang struktur dasarnya sama tetapi fungsinya berbeda disebut organ homolog." },
    { q: "Spesiasi alopatrik terjadi karena adanya ...", options: ["isolasi geografis", "mutasi buatan", "seleksi buatan", "hibridisasi"], answer: 0, solution: "1. Populasi yang terpisah tidak dapat saling kawin. 2. Pemisahan dapat terjadi karena gunung, sungai, atau laut. 3. Terbentuknya spesies baru akibat isolasi geografis disebut spesiasi alopatrik." },
    { q: "Fosil manusia purba Pithecanthropus erectus ditemukan pertama kali di ...", options: ["Trinil, Ngawi", "Sangiran", "Wajak", "Ngandong"], answer: 0, solution: "1. Eugene Dubois menemukan fosil manusia purba di Jawa pada 1891. 2. Fosil atap tengkorak tersebut ditemukan di tepi Bengawan Solo. 3. Lokasi penemuannya adalah Trinil, Ngawi, Jawa Timur." },
    { q: "Urutan evolusi manusia yang benar adalah ...", options: ["Australopithecus - Homo habilis - Homo erectus - Homo sapiens", "Homo habilis - Australopithecus - Homo sapiens - Homo erectus", "Homo erectus - Homo habilis - Australopithecus - Homo sapiens", "Australopithecus - Homo erectus - Homo habilis - Homo sapiens"], answer: 0, solution: "1. Manusia purba tertua berjalan tegak adalah Australopithecus. 2. Kemudian muncul Homo habilis (manusia terampil), lalu Homo erectus (berdiri tegak). 3. Terakhir Homo sapiens (manusia modern), sehingga urutannya Australopithecus - Homo habilis - Homo erectus - Homo sapiens." },
    { q: "Bukti evolusi dari perbandingan embrio vertebrata dikemukakan oleh ...", options: ["Haeckel", "Darwin", "Lamarck", "Weismann"], answer: 0, solution: "1. Embrio ikan, katak, ayam, dan manusia awalnya tampak mirip. 2. Kemiripan embrio menunjukkan adanya hubungan kekerabatan. 3. Tokoh yang mengemukakan bukti embriologi ini adalah Ernst Haeckel." },
    { q: "Adanya variasi dalam suatu populasi penting bagi evolusi karena variasi merupakan ...", options: ["bahan seleksi alam", "penghambat mutasi", "penghambat evolusi", "penambah populasi"], answer: 0, solution: "1. Tanpa perbedaan antar individu, seleksi tidak dapat memilih. 2. Seleksi alam bekerja dengan memilih varian yang paling sesuai. 3. Jadi variasi adalah bahan baku (bahan) seleksi alam." },
    { q: "Rekombinasi genetik saat meiosis terjadi melalui peristiwa ...", options: ["pindah silang dan perpasangan bebas kromosom", "mutasi gen", "duplikasi kromosom", "seleksi alam"], answer: 0, solution: "1. Rekombinasi menghasilkan kombinasi gen baru tanpa mengubah gen itu sendiri. 2. Kombinasi baru terbentuk saat kromatid bertukar segmen dan kromosom berpasangan acak. 3. Peristiwa tersebut adalah pindah silang (crossing over) dan asortasi bebas." },
    { q: "Urutan tingkatan organisasi dalam ekologi dari yang terkecil adalah ...", options: ["individu - populasi - komunitas - ekosistem - bioma - biosfer", "populasi - individu - komunitas - biosfer - ekosistem - bioma", "biosfer - bioma - ekosistem - komunitas - populasi - individu", "individu - komunitas - populasi - bioma - ekosistem - biosfer"], answer: 0, solution: "1. Satuan terkecil ekologi adalah individu (satu makhluk hidup). 2. Sekumpulan individu sejenis membentuk populasi, beberapa populasi membentuk komunitas, dan komunitas dengan lingkungannya membentuk ekosistem. 3. Urutan lengkapnya: individu - populasi - komunitas - ekosistem - bioma - biosfer." },
    { q: "Hewan herbivora dalam rantai makanan berperan sebagai konsumen tingkat ...", options: ["produsen", "I", "II", "III"], answer: 1, solution: "1. Produsen (tumbuhan) dimakan langsung oleh hewan pemakan tumbuhan. 2. Hewan pemakan tumbuhan disebut herbivora. 3. Karena memakan produsen secara langsung, herbivora adalah konsumen tingkat I." },
    { q: "Contoh organisme yang berperan sebagai dekomposer (pengurai) adalah ...", options: ["bakteri dan jamur", "tumbuhan hijau", "herbivora", "karnivora"], answer: 0, solution: "1. Sisa makhluk hidup dan kotoran harus diuraikan kembali menjadi zat hara. 2. Pengurai utama bahan organik mati adalah mikroorganisme. 3. Contoh dekomposer adalah bakteri dan jamur." },
    { q: "Kumpulan beberapa rantai makanan yang saling berhubungan disebut ...", options: ["jaring-jaring makanan", "piramida makanan", "daur materi", "suksesi"], answer: 0, solution: "1. Di alam, satu organisme dapat dimakan oleh beberapa jenis pemangsa. 2. Beberapa rantai makanan yang tumpang tindih membentuk anyaman rumit. 3. Anyaman rantai makanan ini disebut jaring-jaring makanan." },
    { q: "Bentuk piramida energi pada setiap ekosistem selalu ...", options: ["tegak (menyempit ke atas)", "terbalik (melebar ke atas)", "tegak atau terbalik", "mendatar"], answer: 0, solution: "1. Energi berpindah dari produsen ke konsumen dengan efisiensi sekitar 10%. 2. Sebagian besar energi hilang sebagai panas di setiap tingkat trofik. 3. Karena energi selalu berkurang ke atas, piramida energi selalu tegak." },
    { q: "Aliran energi dalam ekosistem bersifat ...", options: ["satu arah dan tidak dapat didaur ulang", "dua arah", "melingkar seperti daur materi", "bolak-balik"], answer: 0, solution: "1. Energi matahari ditangkap produsen lalu berpindah ke konsumen. 2. Pada tiap perpindahan, sebagian energi hilang sebagai panas dan tidak kembali. 3. Jadi aliran energi bersifat satu arah dan tidak dapat didaur ulang, berbeda dengan daur materi." },
    { q: "Hubungan antara kerbau dan burung jalak merupakan contoh simbiosis ...", options: ["mutualisme", "parasitisme", "komensalisme", "predasi"], answer: 0, solution: "1. Burung jalak memakan kutu yang menempel pada tubuh kerbau. 2. Jalak mendapat makanan, kerbau terbebas dari kutu. 3. Hubungan yang saling menguntungkan ini disebut mutualisme." },
    { q: "Hubungan antara ikan remora dan ikan hiu merupakan contoh simbiosis ...", options: ["mutualisme", "komensalisme", "parasitisme", "predasi"], answer: 1, solution: "1. Ikan remora menempel pada hiu untuk ikut berenang dan memakan sisa makanan hiu. 2. Remora diuntungkan, sedangkan hiu tidak dirugikan maupun diuntungkan. 3. Hubungan satu untung satu tidak terpengaruh ini disebut komensalisme." },
    { q: "Hubungan antara harimau dan rusa merupakan contoh simbiosis ...", options: ["predasi", "mutualisme", "komensalisme", "parasitisme"], answer: 0, solution: "1. Harimau memburu dan memakan rusa. 2. Satu pihak (pemangsa) diuntungkan, pihak lain (mangsa) dirugikan hingga mati. 3. Hubungan makan-dimakan ini disebut predasi." },
    { q: "Suksesi primer dimulai dari ...", options: ["lahan gundul yang belum pernah ada kehidupan", "bekas kebakaran hutan", "ladang yang ditinggalkan", "sawah yang diberakan"], answer: 0, solution: "1. Suksesi adalah perubahan komunitas secara bertahap menuju klimaks. 2. Suksesi primer terjadi di tempat yang benar-benar belum ada kehidupan sebelumnya. 3. Contohnya lahan gundul bekas lava atau batuan yang baru tersingkap." },
    { q: "Bioma padang rumput tropis yang diselingi pepohonan disebut ...", options: ["sabana", "tundra", "taiga", "gurun"], answer: 0, solution: "1. Di daerah tropis dengan musim kemarau panjang terdapat padang rumput luas. 2. Padang rumput ini diselingi pohon-pohon yang jarang. 3. Bioma tersebut disebut sabana." },
    { q: "Bioma dengan curah hujan tinggi, pohon rapat, dan keanekaragaman tertinggi adalah ...", options: ["hutan hujan tropis", "sabana", "stepa", "tundra"], answer: 0, solution: "1. Daerah sekitar khatulistiwa menerima hujan hampir sepanjang tahun. 2. Kondisi hangat dan lembap mendukung tumbuhan berlapis-lapis dan fauna beragam. 3. Bioma tersebut adalah hutan hujan tropis." },
    { q: "Bunga kembang sepatu berwarna merah, kuning, dan putih dalam satu spesies menunjukkan keanekaragaman tingkat ...", options: ["gen", "spesies", "ekosistem", "populasi"], answer: 0, solution: "1. Ketiga bunga tersebut masih satu spesies (Hibiscus rosa-sinensis). 2. Perbedaan warna dalam satu spesies disebabkan perbedaan susunan gen. 3. Jadi ini contoh keanekaragaman tingkat gen." },
    { q: "Berbagai jenis kucing seperti anggora, persia, dan kampung menunjukkan keanekaragaman tingkat ...", options: ["gen", "spesies", "ekosistem", "bioma"], answer: 1, solution: "1. Kucing anggora, persia, dan kampung adalah jenis yang berbeda. 2. Perbedaan antar jenis (takson spesies) dalam satu kelompok menunjukkan keanekaragaman spesies. 3. Jadi ini contoh keanekaragaman tingkat spesies." },
    { q: "Hewan endemik yang hanya ditemukan di Sulawesi adalah ...", options: ["anoa", "komodo", "cendrawasih", "orang utan"], answer: 0, solution: "1. Hewan endemik adalah hewan yang hanya ada di daerah tertentu. 2. Komodo endemik Nusa Tenggara, cendrawasih endemik Papua, orang utan di Sumatra-Kalimantan. 3. Hewan endemik Sulawesi adalah anoa (kerbau kerdil)." },
    { q: "Burung cendrawasih merupakan hewan endemik dari ...", options: ["Sulawesi", "Kalimantan", "Papua", "Jawa"], answer: 2, solution: "1. Burung cendrawasih berbulu indah terkenal sebagai burung surga. 2. Habitat aslinya hanya di hutan-hutan Papua. 3. Jadi cendrawasih adalah hewan endemik Papua." },
    { q: "Penyebab utama kepunahan spesies di alam adalah ...", options: ["perusakan habitat", "seleksi alam", "mutasi", "migrasi"], answer: 0, solution: "1. Spesies punah ketika tidak dapat bertahan dan berkembang biak. 2. Penyebab tercepat saat ini adalah hutan ditebang dan habitat diubah manusia. 3. Jadi penyebab utama kepunahan adalah perusakan habitat." },
    { q: "Pemanasan global dan efek rumah kaca terutama disebabkan meningkatnya gas ...", options: ["CO2", "O2", "N2", "H2"], answer: 0, solution: "1. Gas rumah kaca memerangkap panas matahari di atmosfer. 2. Gas utama yang meningkat akibat pembakaran fosil dan deforestasi adalah karbon dioksida. 3. Jadi penyebab utama efek rumah kaca adalah gas CO2." },
    { q: "Upaya pelestarian makhluk hidup di luar habitat aslinya disebut konservasi ...", options: ["ex situ", "in situ", "cagar alam", "hutan lindung"], answer: 0, solution: "1. Pelestarian dapat dilakukan di dalam maupun di luar habitat asli. 2. Kebun binatang dan kebun raya menampung satwa-tumbuhan jauh dari habitat aslinya. 3. Pelestarian di luar habitat asli disebut konservasi ex situ." },
    { q: "Keanekaragaman hayati Indonesia yang sangat tinggi terutama disebabkan ...", options: ["beriklim tropis dan terletak di antara dua benua", "berpenduduk padat", "banyak gunung berapi", "musim kemarau panjang"], answer: 0, solution: "1. Iklim tropis yang hangat dan lembap mendukung kehidupan beragam. 2. Indonesia juga menjadi pertemuan flora-fauna Asia dan Australia (Wallacea). 3. Jadi keanekaragaman tinggi karena beriklim tropis dan terletak di antara dua benua." },
    { q: "Yoghurt dibuat dengan bantuan bakteri ...", options: ["Lactobacillus bulgaricus", "Rhizopus oryzae", "Saccharomyces cerevisiae", "Aspergillus niger"], answer: 0, solution: "1. Yoghurt adalah susu yang difermentasi hingga mengental asam. 2. Fermentasi asam laktat dilakukan oleh bakteri asam laktat. 3. Bakteri pembuat yoghurt antara lain Lactobacillus bulgaricus dan Streptococcus thermophilus." },
    { q: "Jamur yang berperan dalam pembuatan tempe adalah ...", options: ["Rhizopus oryzae", "Saccharomyces cerevisiae", "Lactobacillus bulgaricus", "Aspergillus wentii"], answer: 0, solution: "1. Tempe dibuat dari biji kedelai yang difermentasi. 2. Fermentasi kedelai menjadi tempe dilakukan oleh jamur benang. 3. Jamur tersebut adalah Rhizopus oryzae." },
    { q: "Saccharomyces cerevisiae berperan dalam pembuatan ...", options: ["tape dan roti", "tempe", "yoghurt", "oncom"], answer: 0, solution: "1. Saccharomyces cerevisiae adalah khamir (yeast) pemfermentasi gula. 2. Hasil fermentasinya berupa alkohol dan gas CO2. 3. Khamir ini dipakai membuat tape dan pengembang roti." },
    { q: "Antibiotik penisilin dihasilkan oleh jamur ...", options: ["Penicillium notatum", "Streptomyces griseus", "Rhizopus oryzae", "Mucor mucedo"], answer: 0, solution: "1. Alexander Fleming menemukan zona bening di sekitar jamur pada cawan bakteri. 2. Jamur tersebut menghasilkan zat antibakteri. 3. Jamur penghasil penisilin adalah Penicillium notatum (chrysogenum)." },
    { q: "Insulin untuk penderita diabetes kini diproduksi menggunakan bakteri ...", options: ["Escherichia coli transgenik", "Saccharomyces liar", "Rhizopus oryzae", "Penicillium notatum"], answer: 0, solution: "1. Insulin manusia disisipkan gennya ke dalam bakteri. 2. Bakteri yang disisipi gen asing (transgenik) memproduksi insulin dalam jumlah besar. 3. Bakteri yang dipakai adalah Escherichia coli transgenik." },
    { q: "Contoh tanaman transgenik yang tahan terhadap hama adalah ...", options: ["jagung Bt", "padi IR64", "kedelai impor", "kapas biasa"], answer: 0, solution: "1. Tanaman transgenik disisipi gen dari organisme lain. 2. Gen dari bakteri Bacillus thuringiensis membuat tanaman beracun bagi hama. 3. Contohnya adalah jagung Bt yang tahan hama." },
    { q: "Kloning domba Dolly dilakukan dengan teknik ...", options: ["transfer inti sel somatik", "fusi sel", "kultur jaringan", "inseminasi buatan"], answer: 0, solution: "1. Dolly adalah hewan hasil kloning pertama dari sel dewasa. 2. Inti sel ambing domba dimasukkan ke sel telur yang intinya dibuang. 3. Teknik ini disebut transfer inti sel somatik." },
    { q: "Enzim yang berfungsi menyambung potongan-potongan DNA dalam rekayasa genetika adalah ...", options: ["ligase", "restriksi", "polimerase", "helikase"], answer: 0, solution: "1. Setelah DNA dipotong enzim restriksi, gen asing perlu disambung ke vektor. 2. Penyambungan rantai DNA memerlukan enzim khusus perekat. 3. Enzim penyambung DNA ini disebut ligase." },
    { q: "Teknologi bayi tabung dalam istilah ilmiah disebut ...", options: ["fertilisasi in vitro", "kloning", "kultur jaringan", "hibridisasi"], answer: 0, solution: "1. Bayi tabung membantu pasangan yang sulit punya anak. 2. Sel telur dibuahi sperma di luar tubuh (dalam cawan laboratorium). 3. Pembuahan di luar tubuh ini disebut fertilisasi in vitro." },
    { q: "Dampak positif bioteknologi di bidang pertanian adalah dihasilkannya ...", options: ["bibit unggul yang tahan hama dan berproduksi tinggi", "hama yang resisten", "alergen baru", "pencemaran genetik"], answer: 0, solution: "1. Bioteknologi modern dapat merakit tanaman transgenik. 2. Tanaman hasil rekayasa dapat tahan hama dan berproduksi lebih tinggi. 3. Jadi dampak positifnya adalah bibit unggul tahan hama dan berproduksi tinggi." }
  ]
};
